/** 将资源行拆为主标题与副文案（参考双栏资源选择器：名称 = 值） */
function splitCollectResourceRowLabel(label: string): { primary: string; secondary?: string } {
  const dash = label.indexOf(' - ')
  if (dash >= 0) {
    return { primary: label.slice(dash + 3).trim(), secondary: label.slice(0, dash).trim() }
  }
  return { primary: label }
}

function CollectResourcePersonAvatar({ name }: { name: string }) {
  const initial = name.trim().slice(0, 1) || '?'
  return (
    <span className="scenario-collect-resource-row-icon scenario-collect-resource-row-icon--person" aria-hidden="true">
      {initial}
    </span>
  )
}

