/** 任务配置正文：将 `@资源名` 渲染为蓝色片段（供底层镜像层使用） */
function collectTaskMentionHighlightNodes(text: string): ReactNode {
  const nodes: ReactNode[] = []
  const re = /@([^\s@]+)/g
  let last = 0
  let i = 0
  let m: RegExpExecArray | null
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) {
      nodes.push(<span key={`p-${i++}`}>{text.slice(last, m.index)}</span>)
    }
    nodes.push(
      <span key={`m-${i++}`} className="collect-task-mention-token">
        {m[0]}
      </span>,
    )
    last = m.index + m[0].length
  }
  if (last < text.length) {
    nodes.push(<span key={`p-${i++}`}>{text.slice(last)}</span>)
  }
  return nodes.length > 0 ? <>{nodes}</> : null
}

/** @ 资源选择弹窗尺寸（px） */
const COLLECT_RESOURCE_POPOVER_HEIGHT = 280
const COLLECT_RESOURCE_POPOVER_WIDTH = 420
/** 高于工作区画布内 fixed 菜单（~10072）与 Joyce 浮层（10000） */
const COLLECT_RESOURCE_POPOVER_Z_INDEX = 10250

type CollectResourcePopoverLayout =
  | { left: number; width: number; placement: 'above'; bottom: number }
  | { left: number; width: number; placement: 'below'; top: number }

/** @ 资源选择弹窗（任务配置 / 条件分支逻辑等共用） */
function CollectTaskResourcePopover({
  open,
  onClose,
  anchorRef,
  onPickResource,
}: {
  open: boolean
  onClose: () => void
  anchorRef: RefObject<HTMLElement | null>
  onPickResource: (label: string) => void
}) {
  const { locale } = useLocale()
  const [resourceQuery, setResourceQuery] = useState('')
  const [activeSectionId, setActiveSectionId] = useState(COLLECT_TASK_RESOURCE_HUMAN_INPUTS_SECTION.id)
  const [popoverBox, setPopoverBox] = useState<CollectResourcePopoverLayout>({
    left: 8,
    width: COLLECT_RESOURCE_POPOVER_WIDTH,
    placement: 'above',
    bottom: 8,
  })
  const popoverRef = useRef<HTMLDivElement>(null)
  const searchId = useId()

  const updatePopoverPosition = useCallback(() => {
    const el = anchorRef.current
    if (!el) return
    const r = el.getBoundingClientRect()
    const margin = 8
    const popoverH = COLLECT_RESOURCE_POPOVER_HEIGHT
    const w = Math.min(COLLECT_RESOURCE_POPOVER_WIDTH, window.innerWidth - margin * 2)
    let left = r.left
    left = Math.max(margin, Math.min(left, window.innerWidth - w - margin))

    const spaceAbove = r.top - margin
    const spaceBelow = window.innerHeight - r.bottom - margin
    const placeAbove = spaceAbove >= popoverH || spaceAbove >= spaceBelow

    if (placeAbove) {
      setPopoverBox({
        left,
        width: w,
        placement: 'above',
        bottom: window.innerHeight - r.top + margin,
      })
      return
    }

    setPopoverBox({
      left,
      width: w,
      placement: 'below',
      top: Math.min(r.bottom + margin, window.innerHeight - margin - popoverH),
    })
  }, [anchorRef])

  useLayoutEffect(() => {
    if (!open) return
    updatePopoverPosition()
    const onScroll = () => updatePopoverPosition()
    window.addEventListener('scroll', onScroll, true)
    window.addEventListener('resize', onScroll)
    return () => {
      window.removeEventListener('scroll', onScroll, true)
      window.removeEventListener('resize', onScroll)
    }
  }, [open, updatePopoverPosition])

  useEffect(() => {
    if (!open) return
    const onDoc = (e: MouseEvent) => {
      const t = e.target as Node
      if (anchorRef.current?.contains(t) || popoverRef.current?.contains(t)) return
      onClose()
    }
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') onClose()
    }
    document.addEventListener('mousedown', onDoc)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', onDoc)
      document.removeEventListener('keydown', onKey)
    }
  }, [open, onClose, anchorRef])

  const resourceSections = useMemo(() => buildCollectTaskResourceSections(locale), [locale])

  const filteredSections = useMemo(() => {
    const qq = resourceQuery.trim().toLowerCase()
    const matchItem = (s: string) =>
      !qq ||
      s.toLowerCase().includes(qq) ||
      s.replace(/\s/g, '').toLowerCase().includes(qq.replace(/\s/g, ''))
    return resourceSections
      .map((sec) => ({
        ...sec,
        items: sec.items.filter(
          (it) =>
            matchItem(it.label) ||
            (it.subtitle && matchItem(it.subtitle)) ||
            (it.badge && matchItem(it.badge)),
        ),
      }))
      .filter((sec) => sec.items.length > 0)
  }, [resourceQuery, resourceSections])

  const activeSection =
    filteredSections.find((s) => s.id === activeSectionId) ?? filteredSections[0] ?? null

  const filteredSectionIdsKey = filteredSections.map((s) => s.id).join(',')

  useEffect(() => {
    if (!open || filteredSections.length === 0) return
    if (!filteredSections.some((s) => s.id === activeSectionId)) {
      setActiveSectionId(filteredSections[0].id)
    }
  }, [open, filteredSectionIdsKey, activeSectionId, filteredSections])

  useEffect(() => {
    if (!open) return
    setResourceQuery('')
    setActiveSectionId(COLLECT_TASK_RESOURCE_HUMAN_INPUTS_SECTION.id)
  }, [open])

  if (!open) return null

  return createPortal(
    <div
      ref={popoverRef}
      className="scenario-collect-resource-popover"
      role="dialog"
      aria-modal="true"
      aria-label="选择可引用的资源"
      lang="zh-CN"
      style={{
        position: 'fixed',
        left: popoverBox.left,
        width: popoverBox.width,
        height: COLLECT_RESOURCE_POPOVER_HEIGHT,
        zIndex: COLLECT_RESOURCE_POPOVER_Z_INDEX,
        ...(popoverBox.placement === 'above'
          ? { bottom: popoverBox.bottom }
          : { top: popoverBox.top }),
      }}
    >
      <div className="scenario-collect-resource-popover-search">
        <input
          id={searchId}
          type="search"
          className="scenario-collect-resource-popover-input"
          lang="zh-CN"
          placeholder="搜索资源…"
          value={resourceQuery}
          onChange={(e) => setResourceQuery(e.target.value)}
          autoComplete="off"
        />
      </div>
      <div className="scenario-collect-resource-popover-body">
        {filteredSections.length === 0 ? (
          <p className="scenario-collect-resource-popover-empty">无匹配资源</p>
        ) : (
          <>
            <nav className="scenario-collect-resource-popover-nav" aria-label="资源分类">
              <ul className="scenario-collect-resource-popover-nav-list">
                {filteredSections.map((sec) => (
                  <li key={sec.id}>
                    <button
                      type="button"
                      className={
                        sec.id === activeSection?.id
                          ? 'scenario-collect-resource-nav-item is-active'
                          : 'scenario-collect-resource-nav-item'
                      }
                      aria-current={sec.id === activeSection?.id ? 'true' : undefined}
                      onClick={() => setActiveSectionId(sec.id)}
                    >
                      <span className="scenario-collect-resource-nav-label">{sec.sidebarLabel}</span>
                      <svg
                        className="scenario-collect-resource-nav-chevron"
                        viewBox="0 0 16 16"
                        width="14"
                        height="14"
                        aria-hidden="true"
                      >
                        <path
                          d="M6 4l4 4-4 4"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="1.5"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        />
                      </svg>
                    </button>
                  </li>
                ))}
              </ul>
            </nav>
            <div className="scenario-collect-resource-popover-panel">
              {activeSection ? (
                <>
                  <p className="scenario-collect-resource-panel-title">
                    <CollectResourceSectionIconGlyph kind={activeSection.sectionIcon} />
                    <span>{activeSection.title}</span>
                  </p>
                  {activeSection.id === 'agents' ? (
                    <ul
                      className="scenario-collect-resource-panel-list scenario-collect-resource-panel-list--drawer-agents"
                      role="listbox"
                      aria-label="选择代理人"
                    >
                      {renderOnboardingDrawerAgentListboxOptions({
                        optionIds: activeSection.items.map((it) => it.id.replace(/^drawer-agent-/, '')),
                        onSelectOption: (optionId) => {
                          onPickResource(COLLECT_AGENT_LABELS[optionId] ?? optionId)
                          onClose()
                          setResourceQuery('')
                        },
                      })}
                    </ul>
                  ) : (
                    <ul className="scenario-collect-resource-panel-list">
                      {activeSection.items.map((it) => {
                        const { primary } = splitCollectResourceRowLabel(it.label)
                        const itemKind = it.itemIcon ?? 'field'
                        return (
                          <li key={it.id}>
                            <button
                              type="button"
                              className={
                                it.summary
                                  ? 'scenario-collect-resource-row scenario-collect-resource-row--summary'
                                  : 'scenario-collect-resource-row'
                              }
                              onClick={() => {
                                onPickResource(it.label)
                                onClose()
                                setResourceQuery('')
                              }}
                            >
                              {itemKind === 'field' ? (
                                <CollectResourceVariableIcon />
                              ) : itemKind === 'person' ? (
                                <CollectResourcePersonAvatar name={primary} />
                              ) : it.itemIcon ? (
                                <CollectResourceRowIconGlyph kind={it.itemIcon} />
                              ) : null}
                              <span
                                className={
                                  it.subtitle && itemKind === 'person'
                                    ? 'scenario-collect-resource-row-text scenario-collect-resource-row-text--inline'
                                    : 'scenario-collect-resource-row-text'
                                }
                              >
                                <span className="scenario-collect-resource-row-primary">{primary}</span>
                                {it.subtitle ? (
                                  itemKind === 'person' ? (
                                    <>
                                      <span className="scenario-collect-resource-row-inline-sep" aria-hidden="true">
                                        ·
                                      </span>
                                      <span className="scenario-collect-resource-row-secondary">{it.subtitle}</span>
                                    </>
                                  ) : (
                                    <span className="scenario-collect-resource-row-secondary">{it.subtitle}</span>
                                  )
                                ) : null}
                              </span>
                              {itemKind === 'field' ? <CollectResourceTypeIcon kind={itemKind} /> : null}
                            </button>
                          </li>
                        )
                      })}
                    </ul>
                  )}
                </>
              ) : null}
            </div>
          </>
        )}
      </div>
    </div>,
    document.body,
  )
}

/** 任务描述编辑器底部：上传 / @ 任务事务（抽屉与「任务配置」/ 条件分支逻辑共用） */
function CollectTaskEditorMentionBar({
  fileInputId,
  fileInputRef,
  onFileChange,
  includeFileInput,
  onPickResource,
  resourceOpen: resourceOpenControlled,
  onResourceOpenChange,
  mentionHintLabel = '任务事务',
  atTriggerId,
  mountResourcePopover = true,
}: {
  fileInputId: string
  fileInputRef: RefObject<HTMLInputElement | null>
  onFileChange: (e: ChangeEvent<HTMLInputElement>) => void
  includeFileInput: boolean
  /** 在资源列表中选择一项后写入任务配置文本框（插入 @资源名） */
  onPickResource?: (label: string) => void
  /** 受控：资源弹窗展开（如分支逻辑输入 @ 时自动打开） */
  resourceOpen?: boolean
  onResourceOpenChange?: (open: boolean) => void
  /** 「@」后展示文案，默认「任务事务」 */
  mentionHintLabel?: string
  /** 可选：供 textarea aria-describedby 引用 */
  atTriggerId?: string
  /** 是否挂载资源弹窗（多实例共用 open 状态时仅一处为 true，避免重复 portal） */
  mountResourcePopover?: boolean
}) {
  const [resourceOpenInternal, setResourceOpenInternal] = useState(false)
  const resourceOpen = resourceOpenControlled ?? resourceOpenInternal
  const setResourceOpen = onResourceOpenChange ?? setResourceOpenInternal
  const atTriggerRef = useRef<HTMLButtonElement>(null)

  return (
    <div className="scenario-collect-drawer-editor-mentionbar" aria-label="输入辅助">
      {includeFileInput ? (
        <input
          ref={fileInputRef}
          id={fileInputId}
          type="file"
          className="sr-only"
          tabIndex={-1}
          multiple
          onChange={onFileChange}
        />
      ) : null}
      <button
        type="button"
        className="scenario-collect-drawer-mentionbar-btn"
        aria-label="上传附件"
        title="上传附件"
        onClick={() => fileInputRef.current?.click()}
      >
        <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true">
          <path
            d="M12 16V4m0 0l3.5 3.5M12 4L8.5 7.5"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          <path
            d="M5 14v4a2 2 0 002 2h10a2 2 0 002-2v-4"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        </svg>
      </button>
      <div className="scenario-collect-drawer-mentionbar-at-wrap">
        <button
          ref={atTriggerRef}
          type="button"
          id={atTriggerId}
          className="scenario-collect-drawer-mentionbar-at-trigger"
          aria-label={`${mentionHintLabel}：选择可引用资源`}
          aria-expanded={resourceOpen && mountResourcePopover}
          aria-haspopup="dialog"
          onClick={() => setResourceOpen(!resourceOpen)}
        >
          <span className="scenario-collect-drawer-mentionbar-at-sym" aria-hidden="true">
            @
          </span>
          <span className="scenario-collect-drawer-mentionbar-hint">{mentionHintLabel}</span>
        </button>
        {mountResourcePopover ? (
          <CollectTaskResourcePopover
            open={resourceOpen}
            onClose={() => setResourceOpen(false)}
            anchorRef={atTriggerRef}
            onPickResource={(label) => onPickResource?.(label)}
          />
        ) : null}
      </div>
    </div>
  )
}

function randomTweakOptimizeMarkdown(src: string): string {
  const trimmed = src.trimEnd()
  const stamp = `*（随机修订 ${Math.random().toString(36).slice(2, 10)} · ${new Date().toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit', second: '2-digit' })}）*`
  return `${trimmed}\n\n---\n${stamp}`
}

