function branchPathRulesAddRuleFiltered(search: string) {
  const q = search.trim().toLowerCase()
  const numbered = BRANCH_PATH_RULES_ADD_RULE_NUMBERED.filter(
    (r) => !q || r.title.toLowerCase().includes(q) || r.num.includes(q),
  )
  const utils = BRANCH_PATH_RULES_ADD_RULE_UTILS.filter((u) => !q || u.label.toLowerCase().includes(q))
  return { numbered, utils }
}

function formatBranchPathRulesZhDateFromIso(iso: string): string | null {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(iso.trim())
  if (!m) return null
  const y = Number(m[1])
  const mo = Number(m[2])
  const d = Number(m[3])
  if (!y || mo < 1 || mo > 12 || d < 1 || d > 31) return null
  return `${y}年${mo}月${d}日`
}

type BranchPathRulesDatePickOffsetUnitId = 'day' | 'week' | 'month'

const BRANCH_PATH_RULES_DATE_PICK_OFFSET_UNITS: { id: BranchPathRulesDatePickOffsetUnitId; label: string }[] = [
  { id: 'day', label: '天' },
  { id: 'week', label: '周' },
  { id: 'month', label: '月' },
]

function branchPathRulesDatePickOffsetUnitLabel(unit: BranchPathRulesDatePickOffsetUnitId | undefined): string {
  return BRANCH_PATH_RULES_DATE_PICK_OFFSET_UNITS.find((u) => u.id === (unit ?? 'day'))?.label ?? '天'
}

/** 将带符号的偏移数量按单位折合成「天」（演示：月按 30 天） */
function branchPathRulesDatePickOffsetAmountToSignedDays(
  amount: number,
  unit: BranchPathRulesDatePickOffsetUnitId | undefined,
): number {
  const u = unit ?? 'day'
  const factor = u === 'week' ? 7 : u === 'month' ? 30 : 1
  return Math.trunc(amount) * factor
}

