/** 主轴内置节点与工作区节点画布卡片统一宽度 */
const WORKFLOW_NODE_WIDTH = 300
/** 条件代理并列子卡间距（与 `.scenario-workflow-branch-subs` gap、连线几何一致） */
const WORKFLOW_BRANCH_SUB_INNER_GAP = 20
/** 子路径列布局版本：递增后会在入职场景下按当前间距重排子卡（避免旧会话残留过宽/过窄间距） */
const BRANCH_SUB_LAYOUT_GENERATION = 9
/** 条件代理子路径卡（信息整理 / 信息补充等）：与主卡同宽 */
const WORKFLOW_BRANCH_SUB_CARD_W = WORKFLOW_NODE_WIDTH

/** 工作区用户新增节点画布宽度（与主轴内置节点一致） */
function workspaceExtraNodeBoardWidth(
  _kindOrNode?: WorkspaceNewNodeKind | Pick<WorkspaceExtraNode, 'compactBoard'>,
): number {
  return WORKFLOW_NODE_WIDTH
}

/** 新节点是否应使用 compact 宽（与条件代理下工作区节点一致） */
function workspaceEndpointIsBranchAgentOutlet(
  fromEndpointId: string,
  extras: readonly WorkspaceExtraNode[],
  removed: readonly OnboardingBoardNodeKey[],
): boolean {
  if (removed.includes('branch')) return false
  if (fromEndpointId === onboardingWorkspaceEdgeEndpoint('branch')) return true
  if (fromEndpointId.startsWith(WORKSPACE_EDGE_BRANCH_SUB_PREFIX)) return true
  const fromNode = extras.find((n) => n.id === fromEndpointId)
  if (fromNode?.compactBoard === true) return true
  if (fromNode?.kind === 'branch-agent') return true
  return false
}
/** 条件代理主卡高度（与 with-icon 卡一致） */
const WORKFLOW_BRANCH_MAIN_CARD_H = 72
/** 条件代理下方并列「信息整理 / 信息补充」子行：与主卡间距 + 子卡高度 */
const WORKFLOW_BRANCH_SUB_ROW_GAP = 28
/** 与画布 `scenario-workflow-card--with-icon`（并行 Agent）同高 */
const WORKFLOW_BRANCH_SUB_CARD_H = 72

const WORKFLOW_NODE_HEIGHT: Record<OnboardingBoardNodeKey, number> = {
  trigger: 103,
  /** 与画布 with-icon 卡 min-height 72px 一致，避免连线端点与连接点纵向错位 */
  collect: 72,
  /** 条件代理：主卡 + 下方并列子分支占位（见画布 DOM） */
  branch: WORKFLOW_BRANCH_MAIN_CARD_H + WORKFLOW_BRANCH_SUB_ROW_GAP + WORKFLOW_BRANCH_SUB_CARD_H,
  /** 与 with-icon 卡片实际高度对齐（并行 Agent 与总控同高 72） */
  master: 72,
  account: 72,
  training: 72,
  office: 72,
}

/**
 * 相邻两节点之间的垂直净空（上一节点底边 → 下一节点顶边）。
 * 仅改此值可统一「节点之间」间距；不改变各节点类型在 WORKFLOW_NODE_HEIGHT 中的高度。
 */
const ONBOARDING_WORKFLOW_LAYER_GAP_Y = 40
/** 主轴默认 Y 坐标布局版本（递增后按新间距重置 createInitialOnboardingNodePos） */
const ONBOARDING_SPINE_LAYOUT_GENERATION = 1

/** 主轴自上而下顺序（默认 Y 与层间间距均按此顺序计算，避免手写累加不一致） */
const ONBOARDING_WORKFLOW_SPINE_ORDER: OnboardingBoardNodeKey[] = [
  'trigger',
  'collect',
  'branch',
  'account',
  'training',
  'office',
  'master',
]

const DEFAULT_ONBOARDING_NODE_POS: Record<OnboardingBoardNodeKey, { x: number; y: number }> = (() => {
  const spineX = 1850
  /** 与 `.scenario-workflow-board` 顶边对齐：首节点（Trigger）卡片顶 = 画板坐标 y=0 */
  let y = 0
  const out: Partial<Record<OnboardingBoardNodeKey, { x: number; y: number }>> = {}
  for (let i = 0; i < ONBOARDING_WORKFLOW_SPINE_ORDER.length; i++) {
    const key = ONBOARDING_WORKFLOW_SPINE_ORDER[i]
    out[key] = { x: spineX, y }
    const gapAfter = i < ONBOARDING_WORKFLOW_SPINE_ORDER.length - 1 ? ONBOARDING_WORKFLOW_LAYER_GAP_Y : 0
    y += WORKFLOW_NODE_HEIGHT[key] + gapAfter
  }
  return out as Record<OnboardingBoardNodeKey, { x: number; y: number }>
})()

/** 自上而下：分支后三段顺序执行，再汇入总控 */
const ONBOARDING_WORKFLOW_EDGES: { from: OnboardingBoardNodeKey; to: OnboardingBoardNodeKey }[] = [
  { from: 'trigger', to: 'collect' },
  { from: 'collect', to: 'branch' },
  /** branch → account 由「信息整理 / 信息补充」并行子卡再汇入，见画布自定义 path */
  { from: 'branch', to: 'account' },
  { from: 'account', to: 'training' },
  { from: 'training', to: 'office' },
  { from: 'office', to: 'master' },
]

/** N 条并列子路径顶边中点的 X（子卡固定宽、整行在主卡宽下居中，与 `.scenario-workflow-branch-subs` 一致） */
function onboardingBranchInfoSubCenterXs(pos: { x: number; y: number }, count: number): number[] {
  if (count < 1) return []
  const innerGap = WORKFLOW_BRANCH_SUB_INNER_GAP
  const subW = WORKFLOW_BRANCH_SUB_CARD_W
  const totalW = count * subW + innerGap * Math.max(0, count - 1)
  const offsetX = (WORKFLOW_NODE_WIDTH - totalW) / 2
  return Array.from({ length: count }, (_, i) => pos.x + offsetX + subW / 2 + i * (subW + innerGap))
}

/** 子路径卡左上角默认位置（相对条件代理主卡 `branch` 左上角，与居中并列布局一致） */
function defaultBranchSubCardTopleft(
  branchPos: { x: number; y: number },
  pathCount: number,
  index: number,
): { x: number; y: number } {
  const cx = onboardingBranchInfoSubCenterXs(branchPos, pathCount)[index]
  return {
    x: cx - WORKFLOW_BRANCH_SUB_CARD_W / 2,
    y: branchPos.y + WORKFLOW_BRANCH_MAIN_CARD_H + WORKFLOW_BRANCH_SUB_ROW_GAP,
  }
}

/** 条件代理主卡底 → 各子卡顶 → 各子卡底 → 账户设置顶（子卡位置为画布绝对坐标） */
function onboardingBranchInfoSubForkEdgePaths(
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  paths: readonly BranchPathDraft[],
  subToplefts: { x: number; y: number }[],
): { id: string; d: string; midX: number; midY: number }[] {
  if (subToplefts.length < 1 || paths.length < 1) return []
  const b = pos.branch
  const a = pos.account
  const branchMainBottomY = b.y + WORKFLOW_BRANCH_MAIN_CARD_H
  const branchCenterX = b.x + WORKFLOW_NODE_WIDTH / 2
  const accountTopY = a.y
  const accountCx = a.x + WORKFLOW_NODE_WIDTH / 2
  const out: { id: string; d: string; midX: number; midY: number }[] = []
  subToplefts.forEach((sub, i) => {
    const path = paths[i]
    if (!path) return
    const cx = sub.x + WORKFLOW_BRANCH_SUB_CARD_W / 2
    const subTopY = sub.y
    const mid = workflowVerticalBezierMidpoint(branchCenterX, branchMainBottomY, cx, subTopY)
    out.push({
      id: `branch-fork-${path.id}`,
      d: workflowVerticalBezierBetweenPoints(branchCenterX, branchMainBottomY, cx, subTopY),
      midX: mid.x,
      midY: mid.y,
    })
  })
  subToplefts.forEach((sub, i) => {
    const path = paths[i]
    if (!path || !branchPathConnectsToDownstream(path)) return
    const cx = sub.x + WORKFLOW_BRANCH_SUB_CARD_W / 2
    const subBottomY = sub.y + WORKFLOW_BRANCH_SUB_CARD_H
    const mid = workflowVerticalBezierMidpoint(cx, subBottomY, accountCx, accountTopY)
    out.push({
      id: `sub-account-${path.id}`,
      d: workflowVerticalBezierBetweenPoints(cx, subBottomY, accountCx, accountTopY),
      midX: mid.x,
      midY: mid.y,
    })
  })
  return out
}

/** 画布子路径副文案：取描述首行单行展示；过长由 CSS 省略，完整内容用 `title` 悬停展示 */
function branchPathCanvasDescFirstLine(description: string): string {
  const raw = (description ?? '').trim()
  if (!raw) return '—'
  return (
    raw
      .split('\n')
      .map((l) => l.trim())
      .find((l) => l.length > 0) ?? raw
  )
}

