const BRANCH_CANVAS_PATH_FALLBACK_SUMMARY_ACCOUNT = '配置系统账户、权限与访问凭证。'
const BRANCH_CANVAS_PATH_FALLBACK_SUMMARY_TRAINING = '分配培训课程并跟踪学习进度。'
const BRANCH_CANVAS_PATH_FALLBACK_SUMMARY_OFFICE = '开通工位、设备、门禁及协作工具。'
const BRANCH_CANVAS_PATH_FALLBACK_SUMMARY_MASTER =
  '生成入职报告：员工档案、IT账户、培训及办公配置。'

/** 工作流画布内置条件代理：两条并列路径 → 信息整理 / 信息补充 Agent 子路径卡 */
function defaultBranchPathsForCanvas(): BranchPathDraft[] {
  return [
    {
      id: 'branch-path-0',
      nextNode: 'info-organize',
      description: BRANCH_CANVAS_PATH_ORGANIZE_DESCRIPTION,
      pathTitle: DEFAULT_BRANCH_ORGANIZE_TITLE,
    },
    {
      id: 'branch-path-1',
      nextNode: 'info-supplement',
      description: BRANCH_CANVAS_PATH_SUPPLEMENT_DESCRIPTION,
      pathTitle: DEFAULT_BRANCH_SUPPLEMENT_TITLE,
    },
  ]
}

/** 用户通过 + New 放到画布上的条件分支节点：仅路径 1，分支逻辑与路径文案、下游节点均为空 */
function defaultBranchPathsForUserAddedNode(nextId: () => string): BranchPathDraft[] {
  return [{ id: nextId(), nextNode: '', description: '' }]
}

/**
 * 条件分支抽屉「下一个节点」与画布子路径 `nextNode` 的合法取值。
 * 须与条件分支示例抽屉 `branchShowcaseDrawerAgentIdsForTitle` 中可选 id 对齐，
 * 否则保存代理人（如 it-provisioning）时无法写入 `nextNode`，画布标题仍停留在「账户设置 Agent」等旧值。
 */
const BRANCH_NEXT_NODE_OPTION_ORDER: readonly string[] = [
  'info-organize',
  'info-supplement',
  'collect',
  'account',
  'it-provisioning',
  'compliance',
  'employee-support',
  'hr',
  'orientation',
  'training',
  'lnd',
  'hr-onboarding-coord',
  'office',
  'master',
]

const BRANCH_NEXT_NODE_OPTIONS: { value: string; label: string }[] = BRANCH_NEXT_NODE_OPTION_ORDER.filter(
  (value) => COLLECT_AGENT_LABELS[value] != null,
).map((value) => ({ value, label: COLLECT_AGENT_LABELS[value] }))

const BRANCH_NEXT_NODE_VALUE_SET = new Set(BRANCH_NEXT_NODE_OPTIONS.map((o) => o.value))

/**
 * 内置演示双路径（信息整理 / 信息补充）：保存后自动绘制子路径 → 账户设置 的汇入线。
 * 抽屉「+ 添加路径」产生的新路径不在此集合内：仅独立子卡 + 主卡分叉线，下方不自动接任何节点。
 */
const BUILTIN_BRANCH_AUTO_DOWNSTREAM_PATH_IDS = new Set(['branch-path-0', 'branch-path-1'])

/** 是否绘制子路径底 → 账户设置 Agent 顶的自动汇入线（与抽屉「下一个节点」选项无关） */
function branchPathConnectsToDownstream(p: BranchPathDraft): boolean {
  return BUILTIN_BRANCH_AUTO_DOWNSTREAM_PATH_IDS.has(p.id)
}

function normalizeBranchPathsForCanvas(paths: readonly BranchPathDraft[]): BranchPathDraft[] {
  return migrateLegacyBuiltinCanvasBranchPaths(paths.map((p) => ({ ...p })))
}

/**
 * 路径是否应在工作区画布展示：须已选「下一个节点」、填写路径描述，或通过「添加路径」选定了节点类型标题。
 * 条件代理抽屉内可保留未配置草稿，保存时不会写入 `canvasBranchPaths`。
 */
/** 工作区条件代理路径：`nextNode` 存连线端点 id（`ws-*` / `__ob:*`） */
function isWorkspaceBranchPathEndpointId(id: string): boolean {
  const v = id.trim()
  if (!v) return false
  if (v.startsWith('ws-')) return true
  return v.startsWith(WORKSPACE_EDGE_ONBOARDING_PREFIX)
}

function branchPathIsConfiguredForCanvas(p: BranchPathDraft): boolean {
  const nn = (p.nextNode ?? '').trim()
  if (nn && BRANCH_NEXT_NODE_VALUE_SET.has(nn)) return true
  if (nn && isWorkspaceBranchPathEndpointId(nn)) return true
  if ((p.pathTitle ?? '').trim()) return true
  if ((p.description ?? '').trim()) return true
  return false
}

/** 主轴子路径：下游为 ws 节点时由工作区节点占据分叉位，不再单独渲染子路径卡 */
function branchPathForkTargetIsWorkspaceNode(p: BranchPathDraft): boolean {
  const nn = (p.nextNode ?? '').trim()
  return nn.startsWith('ws-')
}

function filterBranchPathsForCanvas(paths: readonly BranchPathDraft[]): BranchPathDraft[] {
  return normalizeBranchPathsForCanvas(paths).filter(branchPathIsConfiguredForCanvas)
}

/** 条件代理下新增、尚未选定代理人的子路径（画布仅展示「智能体」占位） */
function branchPathIsNewUnsetAgentPath(p: BranchPathDraft): boolean {
  if (BUILTIN_BRANCH_AUTO_DOWNSTREAM_PATH_IDS.has(p.id)) return false
  if (workspaceExtraAgentListId(p.nextNode)) return false
  if ((p.description ?? '').trim()) return false
  const title = (p.pathTitle ?? '').trim()
  return title === WORKSPACE_EXTRA_AGENT_DRAWER_DEFAULT_TITLE || title === '新智能体'
}

/** 画布子路径标题：优先 pathTitle（如「信息整理Agent」）；否则由 nextNode / 端点解析 */
function branchPathCanvasCardTitle(
  p: BranchPathDraft,
  pathIndex: number,
  resolveEndpointLabel?: (endpointId: string) => string | null,
): string {
  const t = (p.pathTitle ?? '').trim()
  if (t) return t
  const nn = (p.nextNode ?? '').trim()
  if (nn && resolveEndpointLabel) {
    const wsLabel = resolveEndpointLabel(nn)
    if (wsLabel) return wsLabel
  }
  if (nn && BRANCH_NEXT_NODE_VALUE_SET.has(nn)) {
    const opt = BRANCH_NEXT_NODE_OPTIONS.find((o) => o.value === nn)
    if (opt) return opt.label
    const fromLabels = COLLECT_AGENT_LABELS[nn]
    if (fromLabels) return fromLabels
  }
  return `路径 ${pathIndex + 1}`
}

/** 打开内置条件代理抽屉时：纠正无效 nextNode；演示双路径默认 info-organize / info-supplement */
function migrateLegacyBuiltinCanvasBranchPaths(paths: BranchPathDraft[]): BranchPathDraft[] {
  const out = paths.map((p) => ({ ...p }))
  if (
    out.length === 2 &&
    out[0]?.id === 'branch-path-0' &&
    out[1]?.id === 'branch-path-1' &&
    out[0].nextNode === 'account' &&
    out[1].nextNode === 'account'
  ) {
    out[0] = { ...out[0], nextNode: 'info-organize' }
    out[1] = { ...out[1], nextNode: 'info-supplement' }
  }
  return out.map((p) => {
    const nn = (p.nextNode ?? '').trim()
    const accountEp = onboardingWorkspaceEdgeEndpoint('account')
    if (p.id === 'branch-path-0') {
      if (nn === accountEp || nn === 'account') return { ...p, nextNode: 'info-organize' }
      if (!nn || !BRANCH_NEXT_NODE_VALUE_SET.has(nn)) return { ...p, nextNode: 'info-organize' }
    }
    if (p.id === 'branch-path-1') {
      if (nn === accountEp || nn === 'account') return { ...p, nextNode: 'info-supplement' }
      if (!nn || !BRANCH_NEXT_NODE_VALUE_SET.has(nn)) return { ...p, nextNode: 'info-supplement' }
    }
    if (BRANCH_NEXT_NODE_VALUE_SET.has(nn)) return p
    return { ...p, nextNode: '' }
  })
}

