const DELAY_DRAWER_DEFAULT_TIME_TYPE = 'delay' satisfies (typeof DELAY_DRAWER_TIME_TYPE_OPTIONS)[number]['value']

const resolveDelayDrawerTimeTypeDraft = (
  savedTimeType: string | undefined,
  savedMode: string | undefined,
): string => {
  let timeType = savedTimeType ?? DELAY_DRAWER_DEFAULT_TIME_TYPE
  if (timeType === 'relative-wait') {
    const mode = savedMode ?? DELAY_DRAWER_DEFAULT_TIME_TYPE
    timeType = mode
  }
  if (timeType === 'delay-after-queue') return DELAY_DRAWER_DEFAULT_TIME_TYPE
  return DELAY_DRAWER_TIME_TYPE_OPTIONS.some((opt) => opt.value === timeType)
    ? timeType
    : DELAY_DRAWER_DEFAULT_TIME_TYPE
}

