function getAsyncProcessingEventOptionsForApp(
  appId: AsyncProcessingThirdPartyAppId | undefined,
): AsyncProcessingActionEventOption[] {
  if (appId === 'slack') return ASYNC_PROCESSING_SLACK_EVENT_OPTIONS
  return ASYNC_PROCESSING_ACTION_EVENT_OPTIONS
}

function isAsyncProcessingEventValidForApp(
  eventValue: string,
  appId: AsyncProcessingThirdPartyAppId | undefined,
): boolean {
  if (!eventValue) return true
  return getAsyncProcessingEventOptionsForApp(appId).some((opt) => opt.value === eventValue)
}

type AsyncAccountConnectStep = 'confirm' | 'login' | 'verify'

function asyncAccountConnectionKey(nodeId: string, appId: AsyncProcessingThirdPartyAppId): string {
  return `${nodeId}::${appId}`
}

function removeAsyncAccountConnectionsForNode(
  prev: Record<string, boolean>,
  nodeId: string,
): Record<string, boolean> {
  const prefix = `${nodeId}::`
  const hasMatch = Object.keys(prev).some((key) => key === nodeId || key.startsWith(prefix))
  if (!hasMatch) return prev
  const next = { ...prev }
  for (const key of Object.keys(next)) {
    if (key === nodeId || key.startsWith(prefix)) {
      delete next[key]
    }
  }
  return next
}

const ASYNC_ACCOUNT_CONNECT_OPEN_MS = 1000
const ASYNC_ACCOUNT_CONNECT_LOADING_MS = 2200
const ASYNC_ACCOUNT_CONNECT_RESEND_SEC = 30

/**
 * 「添加步骤 / 添加路径」左侧抽屉专用（不含 Trigger）。
 * 画布底部「+」与条件代理「添加路径」共用；「+ New」仍用 `WORKSPACE_NEW_NODE_MENU_OPTIONS`。
 */
const BRANCH_ADD_STEP_DRAWER_MENU_OPTIONS: WorkspaceNewNodeOption[] =
  WORKSPACE_NEW_NODE_MENU_OPTIONS.filter((o) => o.id !== 'trigger')

type WorkspaceNewNodeKind = (typeof WORKSPACE_NEW_NODE_OPTIONS)[number]['id']

/**
 * 用户「+ New」节点外框高度（用于 min-height、连线端点与底部锚点）。
 * 内置主轴 `branch` 的 WORKFLOW_NODE_HEIGHT 含主卡 + 下方子路径占位；用户新增的条件分支/条件代理仅为一张主卡样式 with-icon 卡，
 * 与样式 `.scenario-workflow-card--workspace-extra-agent:has(.icon-wrap--branch)` 的 min-height（WORKFLOW_BRANCH_MAIN_CARD_H）一致。
 */
const WORKSPACE_NEW_NODE_HEIGHT: Record<WorkspaceNewNodeKind, number> = {
  manual: WORKFLOW_NODE_HEIGHT.collect + 44,
  agent: WORKFLOW_NODE_HEIGHT.collect,
  trigger: WORKFLOW_NODE_HEIGHT.trigger,
  branch: WORKFLOW_BRANCH_MAIN_CARD_H,
  'branch-agent': WORKFLOW_BRANCH_MAIN_CARD_H,
  delay: WORKFLOW_NODE_HEIGHT.collect,
  async: WORKFLOW_NODE_HEIGHT.collect,
  schedule: WORKFLOW_NODE_HEIGHT.collect + 44,
}

type WorkspaceExtraNode = {
  id: string
  kind: WorkspaceNewNodeKind
  x: number
  y: number
  title?: string
  /** 异步处理节点：所选第三方应用 */
  asyncAppId?: AsyncProcessingThirdPartyAppId
  /** 与子路径卡同宽（条件代理下添加的账户配置等） */
  compactBoard?: boolean
  /** 用户新增的「条件分支 / 条件代理」节点独立配置（kind 为 branch 或 branch-agent 时使用） */
  branchLogicText?: string
  branchPaths?: BranchPathDraft[]
}

/** 工作区用户新增节点之间的连线（from → to） */
type WorkspaceExtraEdge = {
  id: string
  from: string
  to: string
}

/** 从底部线柄拖出、到顶部线柄释放的临时状态 */
type WorkspaceEdgeConnectDragState = {
  fromEndpointId: string
  startX: number
  startY: number
  previewX: number
  previewY: number
}

type WorkflowInsertedEdgeDisconnectSpec =
  | { kind: 'spine'; edgeKey: string }
  | { kind: 'branch-fork'; edgeKey: string }
  | { kind: 'workspace'; edgeId: string }

/** 事件是否起自连线手柄（须避免触发节点拖拽 / pointer capture） */
function isWorkflowEdgeConnectHandleEventTarget(target: EventTarget | null): boolean {
  return target instanceof Element && target.closest('[data-workflow-edge-handle]') != null
}

/** 内置画布节点作为边端点时的 id（与 ws-* 区分） */
const WORKSPACE_EDGE_ONBOARDING_PREFIX = '__ob:'
const WORKSPACE_EDGE_BRANCH_SUB_PREFIX = `${WORKSPACE_EDGE_ONBOARDING_PREFIX}branch-sub:`
const WORKSPACE_EDGE_MANUAL_BRANCH_PREFIX = '__ws-manual-branch:'

function onboardingWorkspaceEdgeEndpoint(key: OnboardingBoardNodeKey): string {
  return `${WORKSPACE_EDGE_ONBOARDING_PREFIX}${key}`
}

function onboardingBranchSubWorkspaceEdgeEndpoint(pathId: string): string {
  return `${WORKSPACE_EDGE_BRANCH_SUB_PREFIX}${pathId}`
}

function workspaceManualBranchEndpoint(nodeId: string, branch: ManualDecisionBranch): string {
  return `${WORKSPACE_EDGE_MANUAL_BRANCH_PREFIX}${nodeId}:${branch}`
}

function parseWorkspaceManualBranchEndpoint(id: string): { nodeId: string; branch: ManualDecisionBranch } | null {
  if (!id.startsWith(WORKSPACE_EDGE_MANUAL_BRANCH_PREFIX)) return null
  const raw = id.slice(WORKSPACE_EDGE_MANUAL_BRANCH_PREFIX.length)
  const splitAt = raw.lastIndexOf(':')
  if (splitAt <= 0) return null
  const nodeId = raw.slice(0, splitAt)
  const branch = raw.slice(splitAt + 1)
  if (branch !== 'agree' && branch !== 'reject') return null
  return { nodeId, branch }
}

function workspaceEdgeEndpointBelongsToNode(endpointId: string, nodeId: string): boolean {
  if (endpointId === nodeId) return true
  return parseWorkspaceManualBranchEndpoint(endpointId)?.nodeId === nodeId
}

function onboardingBranchSubPathIdFromWorkspaceEdgeEndpoint(id: string): string | null {
  if (!id.startsWith(WORKSPACE_EDGE_BRANCH_SUB_PREFIX)) return null
  return id.slice(WORKSPACE_EDGE_BRANCH_SUB_PREFIX.length) || null
}

function onboardingKeyFromWorkspaceEdgeEndpoint(id: string): OnboardingBoardNodeKey | null {
  if (!id.startsWith(WORKSPACE_EDGE_ONBOARDING_PREFIX)) return null
  const k = id.slice(WORKSPACE_EDGE_ONBOARDING_PREFIX.length) as OnboardingBoardNodeKey
  return (ONBOARDING_BOARD_NODE_KEYS as readonly string[]).includes(k) ? k : null
}

type WorkspaceBranchOutgoingTarget = {
  edgeId: string
  endpointId: string
  label: string
}

/**
 * 「添加路径」在主轴条件代理下追加节点时：若已有工作区链，新边应从链末端 ws 出发，
 * 避免多条边都从 __ob:branch 分叉导致工作区条件代理抽屉看不到下游。
 */
function resolveAnchorBelowOnboardingBranchTailFromId(
  branchEndpointId: string,
  edges: readonly WorkspaceExtraEdge[],
  disconnectedEdgeIds: readonly string[],
  extras: readonly WorkspaceExtraNode[],
): string {
  const disconnected = new Set(disconnectedEdgeIds)
  let tail = branchEndpointId
  const visited = new Set<string>()
  while (!visited.has(tail)) {
    visited.add(tail)
    const outs = edges.filter(
      (e) =>
        e.from === tail &&
        !disconnected.has(e.id) &&
        extras.some((n) => n.id === e.to),
    )
    if (outs.length === 0) break
    let pick = outs[0]
    let pickBottom = -Infinity
    for (const e of outs) {
      const n = extras.find((x) => x.id === e.to)
      if (!n) continue
      const bottom = n.y + WORKSPACE_NEW_NODE_HEIGHT[n.kind]
      if (bottom >= pickBottom) {
        pickBottom = bottom
        pick = e
      }
    }
    tail = pick.to
  }
  return tail
}

function isActiveWorkspaceExtraNodeId(
  id: string,
  extras: readonly WorkspaceExtraNode[],
): boolean {
  return id.startsWith('ws-') && extras.some((n) => n.id === id)
}

/**
 * 扫描与条件代理出口端点（主卡/子卡/链上 ws）直接相连及链式下游的全部 ws 节点。
 */
function collectWorkspaceTargetsFromBranchOutlets(
  outletIds: readonly string[],
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): WorkspaceBranchOutgoingTarget[] {
  const disconnected = new Set(disconnectedWorkspaceEdgeIds)
  const outletSet = new Set(outletIds)
  const merged = new Map<string, WorkspaceBranchOutgoingTarget>()
  const wsQueue: string[] = []
  const wsVisited = new Set<string>()

  const recordWs = (wsId: string, edgeId: string) => {
    if (!isActiveWorkspaceExtraNodeId(wsId, extras)) return
    const label = resolveBranchPathNextNodeLabel(wsId, extras, removed, agentSavedByNode) ?? wsId
    if (!merged.has(wsId)) {
      merged.set(wsId, { edgeId, endpointId: wsId, label })
    }
    if (!wsVisited.has(wsId)) {
      wsVisited.add(wsId)
      wsQueue.push(wsId)
    }
  }

  for (const e of edges) {
    if (disconnected.has(e.id)) continue
    if (outletSet.has(e.from) && isActiveWorkspaceExtraNodeId(e.to, extras)) {
      recordWs(e.to, e.id)
    }
    if (outletSet.has(e.to) && isActiveWorkspaceExtraNodeId(e.from, extras)) {
      recordWs(e.from, e.id)
    }
  }

  while (wsQueue.length > 0) {
    const wsId = wsQueue.shift()!
    for (const e of edges) {
      if (disconnected.has(e.id)) continue
      if (e.from !== wsId) continue
      if (!isActiveWorkspaceExtraNodeId(e.to, extras)) continue
      recordWs(e.to, e.id)
    }
  }

  return [...merged.values()]
}

/** ws 节点是否挂在主轴内置条件代理出口下（主卡/子路径卡或其后 ws 链） */
function workspaceNodeIsAttachedToBuiltinBranchZone(
  nodeId: string,
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
): boolean {
  if (removed.includes('branch')) return false
  const branchEp = onboardingWorkspaceEdgeEndpoint('branch')
  const disconnected = new Set(disconnectedWorkspaceEdgeIds)
  const queue: string[] = [nodeId]
  const visited = new Set<string>()

  while (queue.length > 0) {
    const cur = queue.shift()!
    if (visited.has(cur)) continue
    visited.add(cur)

    for (const e of edges) {
      if (disconnected.has(e.id)) continue
      if (e.to !== cur) continue
      if (e.from === branchEp || e.from.startsWith(WORKSPACE_EDGE_BRANCH_SUB_PREFIX)) {
        return true
      }
      if (e.from.startsWith('ws-')) {
        queue.push(e.from)
      }
    }
  }
  return false
}

/** @deprecated 别名，统一走 collectWorkspaceTargetsFromBranchOutlets */
function workspaceWsTargetsReachableFromBranchOutlet(
  fromEndpointId: string,
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): WorkspaceBranchOutgoingTarget[] {
  return collectWorkspaceTargetsFromBranchOutlets(
    [fromEndpointId],
    edges,
    disconnectedWorkspaceEdgeIds,
    removed,
    extras,
    agentSavedByNode,
  )
}

/** 从若干端点收集出口下 ws 链可达节点（条件代理路径下拉共用） */
function branchPathDrawerOutgoingTargetsFromEndpoints(
  fromEndpointIds: readonly string[],
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): WorkspaceBranchOutgoingTarget[] {
  const merged = new Map<string, WorkspaceBranchOutgoingTarget>()
  for (const fromId of fromEndpointIds) {
    for (const t of workspaceWsTargetsReachableFromBranchOutlet(
      fromId,
      edges,
      disconnectedWorkspaceEdgeIds,
      removed,
      extras,
      agentSavedByNode,
    )) {
      merged.set(t.endpointId, t)
    }
  }
  return [...merged.values()]
}

/** 工作区 ws 条件代理：该卡底部拖线直连 ws-*（仅一跳，不含链式下游） */
function workspaceBranchDirectOutgoingTargets(
  branchNodeId: string,
  edges: readonly WorkspaceExtraEdge[],
  disconnectedEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): WorkspaceBranchOutgoingTarget[] {
  const disconnected = new Set(disconnectedEdgeIds)
  const results: WorkspaceBranchOutgoingTarget[] = []
  for (const e of edges) {
    if (e.from !== branchNodeId) continue
    if (disconnected.has(e.id)) continue
    if (!isActiveWorkspaceExtraNodeId(e.to, extras)) continue
    const label = resolveBranchPathNextNodeLabel(e.to, extras, removed, agentSavedByNode) ?? e.to
    results.push({ edgeId: e.id, endpointId: e.to, label })
  }
  return results
}

/** 工作区 ws 条件代理：该卡底部拖线直连 ws-* */
function workspaceBranchOutgoingTargets(
  branchNodeId: string,
  edges: readonly WorkspaceExtraEdge[],
  disconnectedEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): WorkspaceBranchOutgoingTarget[] {
  return branchPathDrawerOutgoingTargetsFromEndpoints(
    [branchNodeId],
    edges,
    disconnectedEdgeIds,
    removed,
    extras,
    agentSavedByNode,
  )
}

/** 演示双路径 fork 直连的子路径 Agent */
const BUILTIN_BRANCH_SUB_AGENT_BY_PATH_ID: Record<string, string> = {
  'branch-path-0': 'info-organize',
  'branch-path-1': 'info-supplement',
}

/** 该路径 fork 直连的子路径 Agent（仅真实节点，不含「路径 N」占位） */
function builtinBranchPathForkConnectedTarget(
  path: BranchPathDraft,
): WorkspaceBranchOutgoingTarget | null {
  const demoAgent = BUILTIN_BRANCH_SUB_AGENT_BY_PATH_ID[path.id]
  if (demoAgent) {
    return {
      edgeId: `branch-fork-${path.id}`,
      endpointId: demoAgent,
      label: COLLECT_AGENT_LABELS[demoAgent] ?? (path.pathTitle ?? demoAgent),
    }
  }
  const nn = (path.nextNode ?? '').trim()
  if (nn && BRANCH_NEXT_NODE_VALUE_SET.has(nn) && nn !== 'account') {
    const title = (path.pathTitle ?? '').trim()
    return {
      edgeId: `branch-fork-${path.id}`,
      endpointId: nn,
      label: title || COLLECT_AGENT_LABELS[nn] || nn,
    }
  }
  return null
}

/** 主轴内置：单条路径「下一个节点」下拉（本子路径卡出口 + 主卡链 + 本路径 fork / 已选 ws） */
function builtinBranchPathDrawerSelectTargets(
  path: BranchPathDraft,
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): WorkspaceBranchOutgoingTarget[] {
  const merged = new Map<string, WorkspaceBranchOutgoingTarget>()
  const disconnected = new Set(disconnectedWorkspaceEdgeIds)
  const subEp = onboardingBranchSubWorkspaceEdgeEndpoint(path.id)
  const fromEndpoints: string[] = [subEp]
  if (!removed.includes('branch')) {
    fromEndpoints.push(onboardingWorkspaceEdgeEndpoint('branch'))
  }

  for (const t of branchPathDrawerOutgoingTargetsFromEndpoints(
    fromEndpoints,
    edges,
    disconnectedWorkspaceEdgeIds,
    removed,
    extras,
    agentSavedByNode,
  )) {
    merged.set(t.endpointId, t)
  }

  for (const e of edges) {
    if (disconnected.has(e.id)) continue
    if (e.from !== subEp) continue
    if (!isActiveWorkspaceExtraNodeId(e.to, extras)) continue
    const label = resolveBranchPathNextNodeLabel(e.to, extras, removed, agentSavedByNode) ?? e.to
    merged.set(e.to, { edgeId: e.id, endpointId: e.to, label })
    for (const t of collectWorkspaceTargetsFromBranchOutlets(
      [e.to],
      edges,
      disconnectedWorkspaceEdgeIds,
      removed,
      extras,
      agentSavedByNode,
    )) {
      merged.set(t.endpointId, t)
    }
  }

  const nn = (path.nextNode ?? '').trim()
  if (nn && isActiveWorkspaceExtraNodeId(nn, extras)) {
    const label = resolveBranchPathNextNodeLabel(nn, extras, removed, agentSavedByNode) ?? nn
    if (!merged.has(nn)) {
      merged.set(nn, { edgeId: `path-persist-${path.id}`, endpointId: nn, label })
    }
  }

  const fork = builtinBranchPathForkConnectedTarget(path)
  if (fork) merged.set(fork.endpointId, fork)

  return [...merged.values()]
}

/**
 * 主轴内置条件代理抽屉：各路径选项的并集（保存 / 自动同步用）。
 */
function builtinBranchDrawerOutgoingTargets(
  mergedPaths: readonly BranchPathDraft[],
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): WorkspaceBranchOutgoingTarget[] {
  const merged = new Map<string, WorkspaceBranchOutgoingTarget>()
  for (const p of mergedPaths) {
    for (const t of builtinBranchPathDrawerSelectTargets(
      p,
      edges,
      disconnectedWorkspaceEdgeIds,
      removed,
      extras,
      agentSavedByNode,
    )) {
      merged.set(t.endpointId, t)
    }
  }
  return [...merged.values()]
}

/** 合并画布 / 抽屉草稿路径行，按索引对齐 id */
function mergeBuiltinBranchDrawerPathRows(
  canvasPaths: readonly BranchPathDraft[],
  drawerPaths: readonly BranchPathDraft[],
): BranchPathDraft[] {
  const n = Math.max(canvasPaths.length, drawerPaths.length)
  const merged: BranchPathDraft[] = []
  for (let i = 0; i < n; i++) {
    const canvasRow = canvasPaths[i]
    const drawerRow = drawerPaths[i]
    if (canvasRow && drawerRow) {
      merged.push({
        ...canvasRow,
        ...drawerRow,
        id: canvasRow.id,
      })
    } else if (canvasRow) {
      merged.push({ ...canvasRow })
    } else if (drawerRow) {
      merged.push({ ...drawerRow })
    }
  }
  return merged.length > 0 ? merged : defaultBranchPathsForCanvas().map((p) => ({ ...p }))
}

function resolveBuiltinPathDirectWsNextNode(
  path: BranchPathDraft,
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  extras: readonly WorkspaceExtraNode[],
): string | null {
  const bound = (path.nextNode ?? '').trim()
  if (bound.startsWith('ws-') && isActiveWorkspaceExtraNodeId(bound, extras)) return bound
  const subEp = onboardingBranchSubWorkspaceEdgeEndpoint(path.id)
  const disconnected = new Set(disconnectedWorkspaceEdgeIds)
  for (const e of edges) {
    if (e.from !== subEp) continue
    if (disconnected.has(e.id)) continue
    if (isActiveWorkspaceExtraNodeId(e.to, extras)) return e.to
  }
  return null
}

/** 主轴内置条件代理抽屉：路径行与画布子路径卡一一对应，nextNode 取自子路径底直连 ws 或演示 fork */
function deriveBuiltinBranchDrawerPaths(
  canvasPaths: readonly BranchPathDraft[],
  existingPaths: readonly BranchPathDraft[],
  edges: readonly WorkspaceExtraEdge[],
  disconnectedWorkspaceEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
): BranchPathDraft[] {
  const existingById = new Map(existingPaths.map((p) => [p.id, p]))
  return canvasPaths.map((cp) => {
    const prev = existingById.get(cp.id)
    const directWs = resolveBuiltinPathDirectWsNextNode(
      cp,
      edges,
      disconnectedWorkspaceEdgeIds,
      extras,
    )
    const fork = builtinBranchPathForkConnectedTarget(cp)
    const targets = builtinBranchPathDrawerSelectTargets(
      cp,
      edges,
      disconnectedWorkspaceEdgeIds,
      removed,
      extras,
      agentSavedByNode,
    )
    const valid = new Set(targets.map((t) => t.endpointId))
    let nn = directWs ?? (prev?.nextNode ?? '').trim() || (cp.nextNode ?? '').trim() || fork?.endpointId || ''
    if (nn && !valid.has(nn)) {
      nn = directWs && valid.has(directWs) ? directWs : fork?.endpointId && valid.has(fork.endpointId) ? fork.endpointId : directWs ?? ''
    }
    return {
      ...cp,
      description: prev?.description ?? cp.description ?? '',
      pathTitle: prev?.pathTitle ?? cp.pathTitle,
      nextNode: nn,
    }
  })
}

/** 工作区 ws 条件代理抽屉：每条直连下游 ws 对应一行路径 */
function deriveWorkspaceBranchDrawerPaths(
  branchNodeId: string,
  existingPaths: readonly BranchPathDraft[],
  edges: readonly WorkspaceExtraEdge[],
  disconnectedEdgeIds: readonly string[],
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  agentSavedByNode: Record<string, string>,
  createPathId: () => string,
): BranchPathDraft[] {
  const direct = workspaceBranchDirectOutgoingTargets(
    branchNodeId,
    edges,
    disconnectedEdgeIds,
    removed,
    extras,
    agentSavedByNode,
  )
  const existingByNext = new Map<string, BranchPathDraft>()
  for (const p of existingPaths) {
    const nn = (p.nextNode ?? '').trim()
    if (nn) existingByNext.set(nn, p)
  }
  return direct.map((t) => {
    const prev = existingByNext.get(t.endpointId)
    return {
      id: prev?.id ?? createPathId(),
      nextNode: t.endpointId,
      description: prev?.description ?? '',
      pathTitle: prev?.pathTitle,
    }
  }).concat(
    existingPaths.filter((p) => {
      const nn = (p.nextNode ?? '').trim()
      if (nn && direct.some((t) => t.endpointId === nn)) return false
      return !direct.some((t) => {
        const prev = existingByNext.get(t.endpointId)
        return prev?.id === p.id
      })
    }).map((p) => ({ ...p })),
  )
}

/**
 * 条件代理抽屉路径行：保留用户路径行；清除无效 nextNode；
 * @deprecated 抽屉路径改由画布直连节点 / 子路径卡推导，见 deriveBuiltinBranchDrawerPaths / deriveWorkspaceBranchDrawerPaths
 */
function normalizeBranchDrawerPaths(
  existingPaths: readonly BranchPathDraft[],
  targets: readonly WorkspaceBranchOutgoingTarget[],
  createPathId: () => string,
  emptyPathsFallback?: () => BranchPathDraft[],
): BranchPathDraft[] {
  const validEndpoints = new Set(targets.map((t) => t.endpointId))
  let paths: BranchPathDraft[] =
    existingPaths.length > 0
      ? existingPaths.map((p) => ({ ...p }))
      : emptyPathsFallback
        ? emptyPathsFallback().map((p) => ({ ...p }))
        : [{ id: createPathId(), nextNode: '', description: '' }]

  paths = paths.map((p) => {
    const nn = (p.nextNode ?? '').trim()
    return {
      ...p,
      nextNode: validEndpoints.has(nn) ? nn : '',
    }
  })

  const usedNext = new Set(
    paths.map((p) => (p.nextNode ?? '').trim()).filter((nn) => nn.length > 0),
  )

  for (const t of targets) {
    if (usedNext.has(t.endpointId)) continue
    const emptyIdx = paths.findIndex((p) => !(p.nextNode ?? '').trim())
    if (emptyIdx >= 0) {
      paths[emptyIdx] = { ...paths[emptyIdx], nextNode: t.endpointId }
      usedNext.add(t.endpointId)
    } else {
      paths.push({
        id: createPathId(),
        nextNode: t.endpointId,
        description: '',
      })
      usedNext.add(t.endpointId)
    }
  }

  return paths
}

function branchPathDrawerSavePaths(
  paths: readonly BranchPathDraft[],
  targets: readonly WorkspaceBranchOutgoingTarget[],
): BranchPathDraft[] {
  const validEndpoints = new Set(targets.map((t) => t.endpointId))
  return paths.map((p) => {
    const nn = (p.nextNode ?? '').trim()
    return {
      ...p,
      nextNode: validEndpoints.has(nn) ? nn : '',
    }
  })
}

function resolveBranchPathNextNodeLabel(
  endpointId: string,
  extras: readonly WorkspaceExtraNode[],
  removed: readonly OnboardingBoardNodeKey[],
  agentSavedByNode: Record<string, string>,
): string | null {
  if (!isWorkspaceBranchPathEndpointId(endpointId)) return null
  const obKey = onboardingKeyFromWorkspaceEdgeEndpoint(endpointId)
  if (obKey != null && !removed.includes(obKey)) {
    return COLLECT_AGENT_LABELS[obKey] ?? obKey
  }
  const n = extras.find((x) => x.id === endpointId)
  if (!n) return null
  if (n.kind === 'agent') {
    const savedId = workspaceExtraAgentListId(agentSavedByNode[n.id])
    if (savedId) return COLLECT_AGENT_LABELS[savedId] ?? savedId
    return WORKSPACE_EXTRA_AGENT_DRAWER_DEFAULT_TITLE
  }
  if (n.kind === 'async') {
    return (n.title ?? '').trim() || getWorkspaceNewNodeOption('async').title
  }
  return getWorkspaceNewNodeOption(n.kind).title
}

function workspaceBranchPathsEqual(a: readonly BranchPathDraft[], b: readonly BranchPathDraft[]): boolean {
  if (a.length !== b.length) return false
  return a.every(
    (p, i) =>
      p.id === b[i].id &&
      p.nextNode === b[i].nextNode &&
      p.description === b[i].description &&
      (p.pathTitle ?? '') === (b[i].pathTitle ?? ''),
  )
}

function workspaceEdgeEndpointBottom(
  endpointId: string,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  branchSubPos?: Record<string, { x: number; y: number }> | null,
): { x: number; y: number } | null {
  const manualBranch = parseWorkspaceManualBranchEndpoint(endpointId)
  if (manualBranch) {
    const node = extras.find((x) => x.id === manualBranch.nodeId)
    if (!node) return null
    const branchX =
      node.x + WORKFLOW_NODE_WIDTH * (manualBranch.branch === 'agree' ? 0.28 : 0.72)
    return {
      x: branchX,
      y: node.y + WORKFLOW_NODE_HEIGHT.collect,
    }
  }
  const subPathId = onboardingBranchSubPathIdFromWorkspaceEdgeEndpoint(endpointId)
  if (subPathId && branchSubPos?.[subPathId]) {
    const s = branchSubPos[subPathId]
    return {
      x: s.x + WORKFLOW_BRANCH_SUB_CARD_W / 2,
      y: s.y + WORKFLOW_BRANCH_SUB_CARD_H,
    }
  }
  const ok = onboardingKeyFromWorkspaceEdgeEndpoint(endpointId)
  if (ok != null) {
    if (removed.includes(ok)) return null
    const h = ok === 'branch' ? WORKFLOW_BRANCH_MAIN_CARD_H : WORKFLOW_NODE_HEIGHT[ok]
    return { x: pos[ok].x + WORKFLOW_NODE_WIDTH / 2, y: pos[ok].y + h }
  }
  const n = extras.find((x) => x.id === endpointId)
  if (!n) return null
  const w = workspaceExtraNodeBoardWidth(n)
  return { x: n.x + w / 2, y: n.y + WORKSPACE_NEW_NODE_HEIGHT[n.kind] }
}

function workspaceEdgeEndpointTop(
  endpointId: string,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  branchSubPos?: Record<string, { x: number; y: number }> | null,
): { x: number; y: number } | null {
  const manualBranch = parseWorkspaceManualBranchEndpoint(endpointId)
  if (manualBranch) {
    endpointId = manualBranch.nodeId
  }
  const subPathId = onboardingBranchSubPathIdFromWorkspaceEdgeEndpoint(endpointId)
  if (subPathId && branchSubPos?.[subPathId]) {
    const s = branchSubPos[subPathId]
    return { x: s.x + WORKFLOW_BRANCH_SUB_CARD_W / 2, y: s.y }
  }
  const ok = onboardingKeyFromWorkspaceEdgeEndpoint(endpointId)
  if (ok != null) {
    if (removed.includes(ok)) return null
    return { x: pos[ok].x + WORKFLOW_NODE_WIDTH / 2, y: pos[ok].y }
  }
  const n = extras.find((x) => x.id === endpointId)
  if (!n) return null
  return { x: n.x + workspaceExtraNodeBoardWidth(n) / 2, y: n.y }
}

/** 顶部锚点命中区适当放大，便于删线后手动重连 */
const WORKFLOW_EDGE_TARGET_HIT_W = 64
const WORKFLOW_EDGE_TARGET_HIT_HALF_H = 14

function mergeBranchSubPosWithDefaultsForEdgeEndpoints(
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  paths: readonly BranchPathDraft[],
  branchSubPos: Record<string, { x: number; y: number }>,
): Record<string, { x: number; y: number }> {
  const b = pos.branch
  const n = paths.length
  const out: Record<string, { x: number; y: number }> = { ...branchSubPos }
  paths.forEach((bp, bpIdx) => {
    if (!out[bp.id]) {
      out[bp.id] = defaultBranchSubCardTopleft(b, n, bpIdx)
    }
  })
  return out
}

/**
 * 根据指针在 board 坐标系下的位置解析「连线落点」端点 id。
 * 不依赖 document.elementFromPoint，避免捕获阶段、缩放层叠、透明层等导致无法命中 target 手柄。
 */
function findWorkspaceConnectDropEndpointId(
  boardPx: number,
  boardPy: number,
  fromEndpointId: string,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  branchSubPosMerged: Record<string, { x: number; y: number }>,
  canvasBranchPaths: readonly BranchPathDraft[],
): string | null {
  const halfW = WORKFLOW_EDGE_TARGET_HIT_W / 2
  const halfH = WORKFLOW_EDGE_TARGET_HIT_HALF_H
  const candidates: string[] = []
  for (const k of ONBOARDING_BOARD_NODE_KEYS) {
    if (!removed.includes(k)) candidates.push(onboardingWorkspaceEdgeEndpoint(k))
  }
  if (!removed.includes('branch') && canvasBranchPaths.length > 0) {
    for (const bp of canvasBranchPaths) {
      candidates.push(onboardingBranchSubWorkspaceEdgeEndpoint(bp.id))
    }
  }
  for (const n of extras) {
    candidates.push(n.id)
  }
  let best: { id: string; d2: number } | null = null
  for (const id of candidates) {
    if (id === fromEndpointId) continue
    const top = workspaceEdgeEndpointTop(id, pos, removed, extras, branchSubPosMerged)
    if (!top) continue
    if (Math.abs(boardPx - top.x) > halfW || Math.abs(boardPy - top.y) > halfH) continue
    const d2 = (boardPx - top.x) ** 2 + (boardPy - top.y) ** 2
    if (!best || d2 < best.d2) best = { id, d2 }
  }
  return best?.id ?? null
}

function workflowVerticalBezierBetweenPoints(x1: number, y1: number, x2: number, y2: number): string {
  const dy = y2 - y1
  const sign = dy >= 0 ? 1 : -1
  const h = workflowEdgeBezierHandle(dy)
  const cy1 = y1 + sign * h
  const cy2 = y2 - sign * h
  return `M ${x1} ${y1} C ${x1} ${cy1} ${x2} ${cy2} ${x2} ${y2}`
}

/** t=0.5 处贝塞尔点，用于连线中点放置断开按钮 */
function workflowVerticalBezierMidpoint(x1: number, y1: number, x2: number, y2: number): { x: number; y: number } {
  const dy = y2 - y1
  const sign = dy >= 0 ? 1 : -1
  const h = workflowEdgeBezierHandle(dy)
  const cy1 = y1 + sign * h
  const cy2 = y2 - sign * h
  const t = 0.5
  const mt = 1 - t
  const x = mt ** 3 * x1 + 3 * mt ** 2 * t * x1 + 3 * mt * t ** 2 * x2 + t ** 3 * x2
  const y = mt ** 3 * y1 + 3 * mt ** 2 * t * cy1 + 3 * mt * t ** 2 * cy2 + t ** 3 * y2
  return { x, y }
}

function onboardingWorkflowSpineEdgeKey(from: OnboardingBoardNodeKey, to: OnboardingBoardNodeKey): string {
  return `${from}->${to}`
}

/**
 * 默认预置的工作区额外节点：在「账户设置 Agent」与「培训协调 Agent」之间插入
 * 一个「用户配置」节点（manual），并配合 DEFAULT_DISCONNECTED_SPINE_EDGES
 * 隐藏 account → training 的默认主轴连线，使流程改为：account → 用户配置 → training。
 *
 * 注意：这里依赖 onboardingWorkspaceEdgeEndpoint / onboardingWorkflowSpineEdgeKey 等辅助函数
 * 在模块求值时的可见性，所以必须放在它们的声明之后；否则会触发 TDZ ReferenceError。
 */
const DEFAULT_USER_CONFIG_NODE_ID = 'ws-init-user-config'
const DEFAULT_USER_CONFIG_EDGE_IN_ID = 'ws-init-edge-account-userconfig'
const DEFAULT_USER_CONFIG_EDGE_OUT_ID = 'ws-init-edge-userconfig-training'

/** 「用户配置」节点占用的纵向空间（自身高度 + 与下一节点保持的统一层间距） */
const DEFAULT_USER_CONFIG_TRAINING_OFFSET_Y =
  WORKSPACE_NEW_NODE_HEIGHT.manual + ONBOARDING_WORKFLOW_LAYER_GAP_Y

const DEFAULT_WORKSPACE_EXTRA_NODES: WorkspaceExtraNode[] = [
  {
    id: DEFAULT_USER_CONFIG_NODE_ID,
    kind: 'manual',
    title: DEFAULT_MANUAL_NODE_TITLE,
    /** 主轴插入：与 account 左对齐（同 X），间距与其他节点一致 */
    x: DEFAULT_ONBOARDING_NODE_POS.account.x,
    y:
      DEFAULT_ONBOARDING_NODE_POS.account.y +
      WORKFLOW_NODE_HEIGHT.account +
      ONBOARDING_WORKFLOW_LAYER_GAP_Y,
  },
]

const DEFAULT_WORKSPACE_EXTRA_EDGES: WorkspaceExtraEdge[] = [
  {
    id: DEFAULT_USER_CONFIG_EDGE_IN_ID,
    from: onboardingWorkspaceEdgeEndpoint('account'),
    to: DEFAULT_USER_CONFIG_NODE_ID,
  },
  {
    id: DEFAULT_USER_CONFIG_EDGE_OUT_ID,
    from: workspaceManualBranchEndpoint(DEFAULT_USER_CONFIG_NODE_ID, 'agree'),
    to: onboardingWorkspaceEdgeEndpoint('training'),
  },
]

/** 默认即断开 account → training 的主轴连线（让数据由「用户配置」节点中转） */
const DEFAULT_DISCONNECTED_SPINE_EDGES: string[] = [
  onboardingWorkflowSpineEdgeKey('account', 'training'),
]

/**
 * 默认入职画布节点初始位置：在 DEFAULT_ONBOARDING_NODE_POS 基础上，将 training 及其
 * 后续节点向下平移「用户配置」节点占用的纵向空间，保证各节点间距统一。
 */
function createInitialOnboardingNodePos(): Record<OnboardingBoardNodeKey, { x: number; y: number }> {
  const next: Record<OnboardingBoardNodeKey, { x: number; y: number }> = {
    ...DEFAULT_ONBOARDING_NODE_POS,
  }
  const shiftKeys: OnboardingBoardNodeKey[] = ['training', 'office', 'master']
  for (const k of shiftKeys) {
    next[k] = {
      x: DEFAULT_ONBOARDING_NODE_POS[k].x,
      y: DEFAULT_ONBOARDING_NODE_POS[k].y + DEFAULT_USER_CONFIG_TRAINING_OFFSET_Y,
    }
  }
  return next
}

function onboardingWorkflowEdgeMidpoint(
  from: OnboardingBoardNodeKey,
  to: OnboardingBoardNodeKey,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
): { x: number; y: number } {
  const x1 = pos[from].x + WORKFLOW_NODE_WIDTH / 2
  const y1 = pos[from].y + WORKFLOW_NODE_HEIGHT[from]
  const x2 = pos[to].x + WORKFLOW_NODE_WIDTH / 2
  const y2 = pos[to].y
  return workflowVerticalBezierMidpoint(x1, y1, x2, y2)
}

function onboardingWorkflowEdgeMidpointToPoint(
  from: OnboardingBoardNodeKey,
  toPoint: { x: number; y: number },
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
): { x: number; y: number } {
  const x1 = pos[from].x + WORKFLOW_NODE_WIDTH / 2
  const y1 = pos[from].y + WORKFLOW_NODE_HEIGHT[from]
  return workflowVerticalBezierMidpoint(x1, y1, toPoint.x, toPoint.y)
}

function workspaceMixedExtraEdgePath(
  fromId: string,
  toId: string,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  branchSubPos?: Record<string, { x: number; y: number }> | null,
): string | null {
  const p1 = workspaceEdgeEndpointBottom(fromId, pos, removed, extras, branchSubPos)
  const p2 = workspaceEdgeEndpointTop(toId, pos, removed, extras, branchSubPos)
  if (!p1 || !p2) return null
  return workflowVerticalBezierBetweenPoints(p1.x, p1.y, p2.x, p2.y)
}

function workspaceMixedExtraEdgeMidpoint(
  fromId: string,
  toId: string,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  branchSubPos?: Record<string, { x: number; y: number }> | null,
): { x: number; y: number } | null {
  const p1 = workspaceEdgeEndpointBottom(fromId, pos, removed, extras, branchSubPos)
  const p2 = workspaceEdgeEndpointTop(toId, pos, removed, extras, branchSubPos)
  if (!p1 || !p2) return null
  return workflowVerticalBezierMidpoint(p1.x, p1.y, p2.x, p2.y)
}

