/** 「通知」Slack 接收者：插入浮层内示例成员 / 频道（演示） */
function generateHitlNoticeSlackPickerList(count = 5): string[] {
  const pool = [
    '@zhang.san',
    '@lisi-hr',
    '@wangwu-it',
    '@onboarding-bot',
    '#hire-ops',
    '#team-onboarding',
    'U01HR9AB2C',
    'U02TEAM3XY',
    'U03OPS1DEF',
  ]
  const shuffled = [...pool].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, Math.min(count, pool.length))
}

/** 「通知」邮件接收者：插入浮层内随机生成的示例邮箱（演示，4～5 条） */
function generateHitlNoticeEmailPickerList(count = 5): string[] {
  const domains = ['example.com', 'example.net', 'mail.demo', 'sandbox.test', 'notify.local']
  const prefixes = [
    'noreply',
    'alerts',
    'team',
    'product',
    'dev',
    'qa',
    'onboarding',
    'hr',
    'sales',
    'support',
    'user',
    'admin',
    'notify',
    'contact',
    'info',
    'help',
    'ops',
    'billing',
  ]
  const used = new Set<string>()
  const out: string[] = []
  let tries = 0
  while (out.length < count && tries < 100) {
    tries += 1
    const p = prefixes[Math.floor(Math.random() * prefixes.length)]
    const n = Math.floor(Math.random() * 90000) + 1000
    const d = domains[Math.floor(Math.random() * domains.length)]
    const e = `${p}+${n}@${d}`
    if (used.has(e)) continue
    used.add(e)
    out.push(e)
  }
  return out.sort((a, b) => a.localeCompare(b))
}

