type HitlInputFormOperationChannel = 'email' | 'slack'

const HITL_NOTICE_RECIPIENT_EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/

/** 将输入框中的片段按分隔符拆分；邮箱渠道仅接受合法邮箱，其余留在 remainder */
function splitNoticeRecipientCommitDraft(
  raw: string,
  channel: HitlInputFormOperationChannel,
): { accepted: string[]; remainder: string } {
  const segments = raw
    .split(/[,;\n]+/)
    .map((s) => s.trim())
    .filter(Boolean)
  if (!segments.length) return { accepted: [], remainder: '' }
  const accepted: string[] = []
  const rejected: string[] = []
  for (const seg of segments) {
    if (channel === 'slack' || HITL_NOTICE_RECIPIENT_EMAIL_RE.test(seg)) accepted.push(seg)
    else rejected.push(seg)
  }
  return { accepted, remainder: rejected.join(', ') }
}

function mergeUniqueNoticeRecipients(prev: string[], additions: string[]): string[] {
  const seen = new Set(prev.map((x) => x.toLowerCase()))
  const next = [...prev]
  for (const t of additions) {
    const low = t.toLowerCase()
    if (!seen.has(low)) {
      seen.add(low)
      next.push(t)
    }
  }
  return next
}

type HitlOpConfigCustomSelectOpen = null | 'notice-channel' | 'notice-message-route'

type HitlNoticeMessageRoute = 'channel' | 'user' | null

function hitlNoticeChannelTriggerLabel(
  value: string,
  route: HitlNoticeMessageRoute,
  channel: HitlInputFormOperationChannel,
): string {
  if (route === null) return '请先选择消息类型'
  if (!value) return '请选择...'
  const list =
    route === 'channel'
      ? channel === 'slack'
        ? HITL_NOTICE_SLACK_CHANNEL_OPTIONS
        : HITL_NOTICE_EMAIL_CHANNEL_OPTIONS
      : channel === 'slack'
        ? HITL_NOTICE_SLACK_USER_OPTIONS
        : HITL_NOTICE_EMAIL_USER_OPTIONS
  return list.find((o) => o.value === value)?.label ?? value
}

