function clampAgentIdForDrawer(nodeKey: OnboardingAgentDrawerKey, preferred: string): string {
  const ids = ONBOARDING_DRAWER_AGENT_LIST_IDS
  if (ids.includes(preferred)) return preferred
  if (preferred === nodeKey) {
    const mapped = DRAWER_AGENT_CANVAS_ID_TO_LIST_ID[nodeKey]
    if (ids.includes(mapped)) return mapped
  }
  return ids.includes(nodeKey) ? nodeKey : ids[0]
}

