function workspaceExtraAgentListId(agentId: string | undefined): string | null {
  const v = (agentId ?? '').trim()
  if (!v || !ONBOARDING_DRAWER_AGENT_LIST_IDS.includes(v)) return null
  return v
}

function workspaceExtraAgentDrawerTitle(
  savedAgentId: string | undefined,
  draftAgentId: string,
): string {
  const id = workspaceExtraAgentListId(draftAgentId) ?? workspaceExtraAgentListId(savedAgentId)
  if (!id) return WORKSPACE_EXTRA_AGENT_DRAWER_DEFAULT_TITLE
  return COLLECT_AGENT_LABELS[id] ?? id
}

/** 子路径 showcase 抽屉：内置演示路径或已选「下一个节点」才预填代理人；用户新增路径保持未选 */
function branchShowcaseInitialAgentId(
  path: BranchPathDraft,
  canvasTitle: string,
  savedAgentId: string | undefined,
  allowedIds: readonly string[],
): string {
  const saved = workspaceExtraAgentListId(savedAgentId)
  if (saved && allowedIds.includes(saved)) return saved
  const nn = (path.nextNode ?? '').trim()
  if (BRANCH_NEXT_NODE_VALUE_SET.has(nn) && allowedIds.includes(nn)) return nn
  if (BUILTIN_BRANCH_AUTO_DOWNSTREAM_PATH_IDS.has(path.id)) {
    const fallback = defaultBranchShowcaseAgentIdForCanvasTitle(canvasTitle)
    return allowedIds.includes(fallback) ? fallback : ''
  }
  return ''
}

