function collectDrawerAgentListFnv1a32(input: string): number {
  let h = 2166136261
  for (let i = 0; i < input.length; i++) {
    h ^= input.charCodeAt(i)
    h = Math.imul(h, 16777619)
  }
  return h >>> 0
}

/** 稳定选出 3～4 个 agentId：在「选择代理人」listbox 中用与跳转区一致的双人团队 SVG（managerial） */
function collectDrawerAgentListTeamSilhouetteIdSet(agentIds: readonly string[], salt: string): Set<string> {
  const pool = agentIds.filter((id) => !DRAWER_AGENT_OPTION_ALWAYS_SINGLE_IDS.has(id))
  if (pool.length === 0) return new Set()
  const count = Math.min(pool.length, 3 + (collectDrawerAgentListFnv1a32(salt) % 2))
  const scored = pool.map((id) => ({ id, s: collectDrawerAgentListFnv1a32(`${id}\0${salt}`) }))
  scored.sort((a, b) => (a.s === b.s ? a.id.localeCompare(b.id) : a.s - b.s))
  return new Set(scored.slice(0, count).map((x) => x.id))
}

/** listbox / 跳转区：当前节点主代理人用节点 pill；其余命中团队剪影集合的用 managerial */
function drawerAgentOptionIconKind(
  optionId: string,
  nodeKey: OnboardingAgentDrawerKey | null,
  nodePillKind: 'single' | 'managerial',
  teamSilhouetteIds: Set<string>,
): 'single' | 'managerial' {
  if (nodeKey != null && optionId === nodeKey) return nodePillKind
  if (DRAWER_AGENT_OPTION_ALWAYS_SINGLE_IDS.has(optionId)) return 'single'
  if (teamSilhouetteIds.has(optionId)) return 'managerial'
  return nodePillKind
}

/** 入职抽屉「选择代理人」listbox：与信息收集节点下拉同序、同标题、同图标抽样 */
function getOnboardingDrawerAgentListIconKind(optionId: string): 'single' | 'managerial' {
  const teamSilhouetteIds = collectDrawerAgentListTeamSilhouetteIdSet(
    ONBOARDING_DRAWER_AGENT_LIST_IDS,
    'collect',
  )
  return drawerAgentOptionIconKind(optionId, 'collect', DRAWER_PILL_KIND.collect, teamSilhouetteIds)
}

