function computeOnboardingWorkflowBounds(
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  branchSubToplefts?: { x: number; y: number }[],
): { minX: number; minY: number; maxX: number; maxY: number } {
  let minX = Infinity
  let minY = Infinity
  let maxX = -Infinity
  let maxY = -Infinity
  for (const k of ONBOARDING_BOARD_NODE_KEYS) {
    const p = pos[k]
    const h = WORKFLOW_NODE_HEIGHT[k]
    minX = Math.min(minX, p.x)
    minY = Math.min(minY, p.y)
    maxX = Math.max(maxX, p.x + WORKFLOW_NODE_WIDTH)
    maxY = Math.max(maxY, p.y + h)
  }
  if (branchSubToplefts && branchSubToplefts.length > 0) {
    for (const s of branchSubToplefts) {
      minX = Math.min(minX, s.x)
      minY = Math.min(minY, s.y)
      maxX = Math.max(maxX, s.x + WORKFLOW_BRANCH_SUB_CARD_W)
      maxY = Math.max(maxY, s.y + WORKFLOW_BRANCH_SUB_CARD_H)
    }
  }
  return { minX, minY, maxX, maxY }
}

/** 画布底部「+ 添加步骤」锚点：最靠下的节点底边、中心 X，以及用于连线的端点 id（内置 __ob: 或 ws-*） */
function workflowBoardBottomAddLinkAnchor(
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
): { top: number; centerX: number; fromEndpointId: string } | null {
  let anchorBottom = 0
  let anchorCenterX = pos.master.x + WORKFLOW_NODE_WIDTH / 2
  let fromEndpointId: string | null = null
  let any = false
  for (const k of ONBOARDING_WORKFLOW_SPINE_ORDER) {
    if (removed.includes(k)) continue
    any = true
    const b = pos[k].y + WORKFLOW_NODE_HEIGHT[k]
    if (b >= anchorBottom) {
      anchorBottom = b
      anchorCenterX = pos[k].x + WORKFLOW_NODE_WIDTH / 2
      fromEndpointId = onboardingWorkspaceEdgeEndpoint(k)
    }
  }
  for (const n of extras) {
    any = true
    const b = n.y + WORKSPACE_NEW_NODE_HEIGHT[n.kind]
    if (b >= anchorBottom) {
      anchorBottom = b
      anchorCenterX = n.x + workspaceExtraNodeBoardWidth(n) / 2
      fromEndpointId = n.id
    }
  }
  if (!any || !fromEndpointId) return null
  return { top: anchorBottom, centerX: anchorCenterX, fromEndpointId }
}

/** 画布上「叶子」节点底部展示的「+ 添加步骤」：仅当下方无连线（主轴 / 分支 fork / 工作区边） */
type WorkflowBoardLeafAddTailItem = {
  key: string
  fromEndpointId: string
  top: number
  centerX: number
}

function onboardingBuiltinNodeHasOutgoingBottomConnection(
  key: OnboardingBoardNodeKey,
  args: {
    removed: readonly OnboardingBoardNodeKey[]
    wsFromSet: ReadonlySet<string>
    disconnectedSpine: readonly string[]
    disconnectedBranchFork: readonly string[]
    hideBranchToAccountSpine: boolean
    branchForkMode: boolean
    canvasBranchPaths: readonly BranchPathDraft[]
  },
): boolean {
  const {
    removed,
    wsFromSet,
    disconnectedSpine,
    disconnectedBranchFork,
    hideBranchToAccountSpine,
    branchForkMode,
    canvasBranchPaths,
  } = args
  if (wsFromSet.has(onboardingWorkspaceEdgeEndpoint(key))) return true
  for (const edge of ONBOARDING_WORKFLOW_EDGES) {
    if (edge.from !== key) continue
    if (removed.includes(edge.from) || removed.includes(edge.to)) continue
    if (hideBranchToAccountSpine && edge.from === 'branch' && edge.to === 'account') continue
    if (disconnectedSpine.includes(onboardingWorkflowSpineEdgeKey(edge.from, edge.to))) continue
    return true
  }
  if (key === 'branch' && branchForkMode && !removed.includes('branch')) {
    for (const p of canvasBranchPaths) {
      if (!disconnectedBranchFork.includes(`branch-fork-${p.id}`)) return true
    }
  }
  return false
}

function onboardingBranchSubHasOutgoingBottomConnection(
  bp: BranchPathDraft,
  bpId: string,
  args: {
    removed: readonly OnboardingBoardNodeKey[]
    wsFromSet: ReadonlySet<string>
    disconnectedBranchFork: readonly string[]
    branchForkMode: boolean
  },
): boolean {
  const { removed, wsFromSet, disconnectedBranchFork, branchForkMode } = args
  if (wsFromSet.has(onboardingBranchSubWorkspaceEdgeEndpoint(bpId))) return true
  if (!branchForkMode || removed.includes('account')) return false
  if (!branchPathConnectsToDownstream(bp)) return false
  return !disconnectedBranchFork.includes(`sub-account-${bpId}`)
}

function computeWorkflowBoardLeafAddTailItems(
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  removed: readonly OnboardingBoardNodeKey[],
  extras: readonly WorkspaceExtraNode[],
  edges: readonly WorkspaceExtraEdge[],
  disconnectedSpine: readonly string[],
  disconnectedBranchFork: readonly string[],
  disconnectedWorkspace: readonly string[],
  hideBranchToAccountSpine: boolean,
  canvasBranchPaths: readonly BranchPathDraft[],
  onboardingBranchSubPosById: Record<string, { x: number; y: number }>,
): WorkflowBoardLeafAddTailItem[] {
  const activeWsEdges = edges.filter((e) => !disconnectedWorkspace.includes(e.id))
  const wsFromSet = new Set(activeWsEdges.map((e) => e.from))
  const branchForkMode = canvasBranchPaths.length > 0
  const nPaths = canvasBranchPaths.length

  const builtinArgs = {
    removed,
    wsFromSet,
    disconnectedSpine,
    disconnectedBranchFork,
    hideBranchToAccountSpine,
    branchForkMode,
    canvasBranchPaths,
  }

  const items: WorkflowBoardLeafAddTailItem[] = []

  for (const key of ONBOARDING_WORKFLOW_SPINE_ORDER) {
    if (removed.includes(key)) continue
    if (onboardingBuiltinNodeHasOutgoingBottomConnection(key, builtinArgs)) continue
    const h = key === 'branch' ? WORKFLOW_BRANCH_MAIN_CARD_H : WORKFLOW_NODE_HEIGHT[key]
    items.push({
      key: `ob-${key}`,
      fromEndpointId: onboardingWorkspaceEdgeEndpoint(key),
      top: pos[key].y + h,
      centerX: pos[key].x + WORKFLOW_NODE_WIDTH / 2,
    })
  }

  if (!removed.includes('branch') && branchForkMode) {
    const b = pos.branch
    for (let bpIdx = 0; bpIdx < canvasBranchPaths.length; bpIdx++) {
      const bp = canvasBranchPaths[bpIdx]
      const subPos =
        onboardingBranchSubPosById[bp.id] ?? defaultBranchSubCardTopleft(b, nPaths, bpIdx)
      if (
        onboardingBranchSubHasOutgoingBottomConnection(bp, bp.id, {
          removed,
          wsFromSet,
          disconnectedBranchFork,
          branchForkMode,
        })
      )
        continue
      items.push({
        key: `ob-branch-sub-${bp.id}`,
        fromEndpointId: onboardingBranchSubWorkspaceEdgeEndpoint(bp.id),
        top: subPos.y + WORKFLOW_BRANCH_SUB_CARD_H,
        centerX: subPos.x + WORKFLOW_BRANCH_SUB_CARD_W / 2,
      })
    }
  }

  for (const n of extras) {
    if (
      n.kind === 'manual' ||
      wsFromSet.has(n.id) ||
      wsFromSet.has(workspaceManualBranchEndpoint(n.id, 'agree')) ||
      wsFromSet.has(workspaceManualBranchEndpoint(n.id, 'reject'))
    ) {
      continue
    }
    items.push({
      key: n.id,
      fromEndpointId: n.id,
      top: n.y + WORKSPACE_NEW_NODE_HEIGHT[n.kind],
      centerX: n.x + workspaceExtraNodeBoardWidth(n) / 2,
    })
  }

  return items
}

/** 与 `.scenario-workflow-canvas` 的 padding 一致，用于把画布坐标换算到可滚动区域 */
const WORKFLOW_CANVAS_PADDING = 12

/** 将指针位置换算为 `.scenario-workflow-board` 内与 SVG viewBox 一致的坐标 */
function clientPointerToBoardCoords(
  boardEl: HTMLElement | null,
  clientX: number,
  clientY: number,
): { x: number; y: number } | null {
  if (!boardEl) return null
  const r = boardEl.getBoundingClientRect()
  if (r.width < 24 || r.height < 24) return null
  return {
    x: ((clientX - r.left) / r.width) * ONBOARDING_BOARD_W,
    y: ((clientY - r.top) / r.height) * ONBOARDING_BOARD_H,
  }
}

/** 视口从主轴第一个仍在画布上的节点开始展示（顶对齐 + 横向居中该节点），避免默认落在整段工作流的几何中心 */
function scrollOnboardingWorkflowToFirstNode(
  vp: HTMLDivElement,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
  zoomPercent: number,
  removed: readonly OnboardingBoardNodeKey[],
) {
  if (!Number.isFinite(zoomPercent) || zoomPercent < 1) return
  const z = zoomPercent / 100
  const removedSet = new Set(removed)
  let firstKey: OnboardingBoardNodeKey = ONBOARDING_WORKFLOW_SPINE_ORDER[0]
  for (const k of ONBOARDING_WORKFLOW_SPINE_ORDER) {
    if (!removedSet.has(k)) {
      firstKey = k
      break
    }
  }
  const p = pos[firstKey]
  const vw = vp.clientWidth
  const vh = vp.clientHeight
  const cx = p.x + WORKFLOW_NODE_WIDTH / 2
  const targetLeft = WORKFLOW_CANVAS_PADDING + cx * z - vw / 2
  const targetTop = WORKFLOW_CANVAS_PADDING + p.y * z
  const maxL = Math.max(0, vp.scrollWidth - vw)
  const maxT = Math.max(0, vp.scrollHeight - vh)
  vp.scrollLeft = Math.min(Math.max(0, targetLeft), maxL)
  vp.scrollTop = Math.min(Math.max(0, targetTop), maxT)
}

/** 整块画布小于视口时，用 margin 在四周留白居中（与滚动定位互补） */
function alignWorkflowCanvasMarginsWhenFits(vp: HTMLDivElement) {
  const canvas = vp.querySelector('.scenario-workflow-canvas')
  if (!(canvas instanceof HTMLElement)) return
  const sw = vp.scrollWidth
  const sh = vp.scrollHeight
  const cw = vp.clientWidth
  const ch = vp.clientHeight
  if (sw <= cw + 1 && sh <= ch + 1) {
    canvas.style.marginLeft = `${Math.max(0, (cw - sw) / 2)}px`
    canvas.style.marginTop = `${Math.max(0, (ch - sh) / 2)}px`
  } else {
    canvas.style.marginLeft = ''
    canvas.style.marginTop = ''
  }
}

/** 竖向贝塞尔控制柄：保证 h ≤ |dy|/2，避免小间距时控制点越过对端导致轨迹折回、端点像悬空 */
function workflowEdgeBezierHandle(dy: number): number {
  const absDy = Math.abs(dy)
  if (absDy < 1e-6) return 2
  const halfRoom = Math.max(2, absDy / 2 - 1)
  const fromSlope = absDy * 0.48
  return Math.min(180, Math.min(halfRoom, fromSlope))
}

function onboardingWorkflowEdgePath(
  from: OnboardingBoardNodeKey,
  to: OnboardingBoardNodeKey,
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
): string {
  const x1 = pos[from].x + WORKFLOW_NODE_WIDTH / 2
  const y1 = pos[from].y + WORKFLOW_NODE_HEIGHT[from]
  const x2 = pos[to].x + WORKFLOW_NODE_WIDTH / 2
  const y2 = pos[to].y
  const dy = y2 - y1
  const sign = dy >= 0 ? 1 : -1
  const h = workflowEdgeBezierHandle(dy)
  const cy1 = y1 + sign * h
  const cy2 = y2 - sign * h
  return `M ${x1} ${y1} C ${x1} ${cy1} ${x2} ${cy2} ${x2} ${y2}`
}

function onboardingWorkflowEdgePathToPoint(
  from: OnboardingBoardNodeKey,
  toPoint: { x: number; y: number },
  pos: Record<OnboardingBoardNodeKey, { x: number; y: number }>,
): string {
  const x1 = pos[from].x + WORKFLOW_NODE_WIDTH / 2
  const y1 = pos[from].y + WORKFLOW_NODE_HEIGHT[from]
  const x2 = toPoint.x
  const y2 = toPoint.y
  const dy = y2 - y1
  const sign = dy >= 0 ? 1 : -1
  const h = workflowEdgeBezierHandle(dy)
  const cy1 = y1 + sign * h
  const cy2 = y2 - sign * h
  return `M ${x1} ${y1} C ${x1} ${cy1} ${x2} ${cy2} ${x2} ${y2}`
}

/** 工作区用户新增节点之间的连线（几何与 onboardingWorkflowEdgePath 一致） */
function workspaceExtraEdgePath(from: WorkspaceExtraNode, to: WorkspaceExtraNode): string {
  const fromW = workspaceExtraNodeBoardWidth(from)
  const toW = workspaceExtraNodeBoardWidth(to)
  return workflowVerticalBezierBetweenPoints(
    from.x + fromW / 2,
    from.y + WORKSPACE_NEW_NODE_HEIGHT[from.kind],
    to.x + toW / 2,
    to.y,
  )
}

function workspaceExtraEdgeMidpoint(from: WorkspaceExtraNode, to: WorkspaceExtraNode): { x: number; y: number } {
  const fromW = workspaceExtraNodeBoardWidth(from)
  const toW = workspaceExtraNodeBoardWidth(to)
  return workflowVerticalBezierMidpoint(
    from.x + fromW / 2,
    from.y + WORKSPACE_NEW_NODE_HEIGHT[from.kind],
    to.x + toW / 2,
    to.y,
  )
}

