function defaultBranchPathCaption(pathIndex: number) {
  if (pathIndex === 0) return '当条件成立时'
  if (pathIndex === 1) return '如果未选择其他路径'
  return '当扩展条件成立时'
}

/** 与画布分支槽位一一对应，用于路径规则抽屉保存的「路径名称」同步到规则条 */
const ONBOARDING_BRANCH_PATH_SLOT_COUNT = 8

function defaultBranchPathSlotTitle(slot: number) {
  if (slot === 0) return '信息完整'
  if (slot === 1) return '信息不完整'
  return `路径${String.fromCharCode(65 + slot)}`
}

