/** 左侧「社招面试」对应的智能体测试流（演示） */
function ScenarioWorkspaceRunsHrInterviewTimeline({ onRunsProgress }: { onRunsProgress?: () => void } = {}) {
  const [step, setStep] = useState(0)
  const [userLine, setUserLine] = useState('')
  const [gate, setGate] = useState(false)
  const settleHo = useCallback(() => setGate(true), [])
  const timeAll = '约 1 分钟前'
  const timeHandover = '刚刚'

  return (
    <div
      className="scenario-workspace-runs-timeline scenario-workspace-runs-timeline--run-chat"
      aria-label="社招面试智能体测试"
    >
      <RunsRunStep kind="collect" displayName="HR 初筛 Agent" timeLabel={timeAll}>
        <RunsUpdateCard
          kind="collect"
          displayName="HR 初筛 Agent"
          streamBody
          choices={
            step === 0 ? (
              <div className="scenario-workspace-runs-flow-quick" role="group" aria-label="初筛结论">
                {RUNS_HR_DEMO_CHOICES.map((c) => (
                  <button
                    key={c.label}
                    type="button"
                    className="scenario-workspace-runs-flow-chip"
                    onClick={() => {
                      onRunsProgress?.()
                      setUserLine(c.line)
                      setStep(1)
                    }}
                  >
                    {c.label}
                  </button>
                ))}
              </div>
            ) : null
          }
        >
          <p className="scenario-workspace-runs-run-lead">
            你好！我是<strong>HR 初筛 Agent</strong>，负责把<strong>简历、岗位匹配度与合规项</strong>压成结构化分数，并在你确认后把<strong>面试提纲与材料包</strong>交给面试官智能体。
          </p>
          <ul className="scenario-workspace-runs-run-list">
            <li>对照岗位 JD 与候选人自述做关键词与年限校验</li>
            <li>标注风险点（空窗、频繁跳槽等）供面试官追问</li>
            <li>你点选结论后触发与「面试官 Agent」的交接</li>
          </ul>
        </RunsUpdateCard>
      </RunsRunStep>

      {step >= 1 ? (
        <>
          <RunsUserTurn text={userLine} />
          <RunsHandoverBar
            key="runs-hr-handover"
            fromKind="collect"
            toKind="training"
            fromDisplayName="HR 初筛 Agent"
            toName="面试官 Agent"
            timeLabel={timeHandover}
            previousWork={RUNS_HANDOVER_HR_TO_INTERVIEW.previousWork}
            preparingMajors={RUNS_HANDOVER_HR_TO_INTERVIEW.preparing}
            readyMajors={RUNS_HANDOVER_HR_TO_INTERVIEW.ready}
            onSettled={settleHo}
          />
          {gate ? (
            <RunsRunStep
              kind="training"
              displayName="面试官 Agent"
              timeLabel={timeAll}
              extraClassName="scenario-workspace-runs-run-step--reveal"
            >
              <RunsUpdateCard kind="training" displayName="面试官 Agent" streamBody>
                <p className="scenario-workspace-runs-run-record">已接收：初筛结论 — {userLine}</p>
                <p className="scenario-workspace-runs-run-lead">
                  你好！我是<strong>面试官 Agent</strong>，将基于<strong>结构化提纲</strong>组织行为题与系统设计追问，并在结束后回写<strong>评分与录用建议</strong>（演示）。
                </p>
                <ul className="scenario-workspace-runs-run-list">
                  <li>首轮：岗位相关行为与协作场景</li>
                  <li>次轮：白板 / 线上编码或方案草图（按职级模板）</li>
                  <li>全程录音转写与要点摘要自动归档</li>
                </ul>
              </RunsUpdateCard>
            </RunsRunStep>
          ) : null}
        </>
      ) : null}
    </div>
  )
}

