  const asyncAccountConnectSuccessToastTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const asyncAccountConnectOpenTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const [workspaceExtraNodes, setWorkspaceExtraNodes] = useState<WorkspaceExtraNode[]>(
    () => DEFAULT_WORKSPACE_EXTRA_NODES.map((n) => ({ ...n })),
  )
  const workspaceExtraNodesRef = useRef(workspaceExtraNodes)
  const [onboardingCanvasTitleByNode, setOnboardingCanvasTitleByNode] = useState<Record<OnboardingBoardNodeKey, string>>(
    () => ({ ...ONBOARDING_CANVAS_DEFAULT_NODE_TITLES }),
  )
  const workspaceExtraIdSeqRef = useRef(1)
  const [workspaceExtraEdges, setWorkspaceExtraEdges] = useState<WorkspaceExtraEdge[]>(
    () => DEFAULT_WORKSPACE_EXTRA_EDGES.map((e) => ({ ...e })),
  )
  const workspaceExtraEdgesRef = useRef(workspaceExtraEdges)
  const [workspaceEdgeConnectDrag, setWorkspaceEdgeConnectDrag] = useState<WorkspaceEdgeConnectDragState | null>(null)
  const workspaceEdgeConnectDragRef = useRef<WorkspaceEdgeConnectDragState | null>(null)
  /** 拖线过程中注销 window 上的 move/up（含 Escape 取消） */
  const workspaceEdgeConnectDetachRef = useRef<(() => void) | null>(null)
  const workflowBoardRef = useRef<HTMLDivElement>(null)
  const [scenarioWorkspaceMode, setScenarioWorkspaceMode] = useState<'editor' | 'run-loading' | 'run-test'>(
    'editor',
  )
  /** 编辑器内：Build（画布）与 Runs（运行对话演示）分段，与顶栏 .agents-workspace-segment 对齐 */
  const [workspaceEditorTab, setWorkspaceEditorTab] = useState<'build' | 'runs'>('build')

  useEffect(() => {
    if (!openScenarioRequest) return
    const raw = openScenarioRequest.name.trim()
    if (!raw) {
      onOpenScenarioRequestConsumed?.()
      return
    }
    const sourceName = resolveOnboardingSourceName(raw, locale) ?? raw
    if (!agents.some((a) => a.name === sourceName)) {
      onOpenScenarioRequestConsumed?.()
      return
    }
    setSelectedScenarioName(sourceName)
    const tab = openScenarioRequest.editorTab
    if (tab === 'runs' || (tab === 'build' && canEditScenario)) {
      setWorkspaceEditorTab(tab)
    } else if (!canEditScenario) {
      setWorkspaceEditorTab('runs')
    }
    onOpenScenarioRequestConsumed?.()
  }, [openScenarioRequest, agents, onOpenScenarioRequestConsumed, locale, canEditScenario])

  const [onboardingTriggerAccentOpen, setOnboardingTriggerAccentOpen] = useState(false)
  /** 工作区用户新增节点：点击后保持左侧蓝条高亮（与 rich Trigger 的 accent-on 一致） */
  const [workspaceExtraNodeAccentOpenId, setWorkspaceExtraNodeAccentOpenId] = useState<string | null>(null)
  /** 工作区新增「智能体」节点：左侧无遮罩配置抽屉（布局同信息收集 Agent 抽屉） */
  const [workspaceExtraAgentDrawerId, setWorkspaceExtraAgentDrawerId] = useState<string | null>(null)
  /** 工作区「用户配置」节点：左侧无遮罩配置抽屉 */
  const [workspaceManualConfigDrawerId, setWorkspaceManualConfigDrawerId] = useState<string | null>(null)
  /** 工作区新增「智能体」抽屉：各节点已保存的代理人 id / 任务文案 */
  const [workspaceAgentDrawerSavedAgentByNode, setWorkspaceAgentDrawerSavedAgentByNode] = useState<
    Record<string, string>
  >({})

  const measureBranchPathAnchor = useCallback(() => {
    const scaleEl = workflowScaleRef.current
    if (!scaleEl) return
    const z = workspaceCanvasZoom / 100
    if (!Number.isFinite(z) || z <= 0) return

    const prefix = `${tabListId}-board-branch`
    const tabEl =
      document.getElementById(`${prefix}-branch-tab-${branchCanvasActivePathIdx}`) ??
      document.getElementById(`${prefix}-branch-tab-overflow`)
    if (!(tabEl instanceof HTMLElement)) {
      setBranchCanvasActivePathAnchorX(null)
      return
    }
    const sRect = scaleEl.getBoundingClientRect()
    const r = tabEl.getBoundingClientRect()
    const xInScalePx = r.left + r.width / 2 - sRect.left
    const x = xInScalePx / z
    if (!Number.isFinite(x)) {
      setBranchCanvasActivePathAnchorX(null)
      return
    }
    setBranchCanvasActivePathAnchorX(x)
  }, [branchCanvasActivePathIdx, tabListId, workspaceCanvasZoom])

  useLayoutEffect(() => {
    measureBranchPathAnchor()
    window.addEventListener('resize', measureBranchPathAnchor)
    return () => window.removeEventListener('resize', measureBranchPathAnchor)
  }, [measureBranchPathAnchor])
  const [workspaceAgentDrawerSavedTaskByNode, setWorkspaceAgentDrawerSavedTaskByNode] = useState<
    Record<string, string>
  >({})
  const [workspaceExtraAgentDraftAgentId, setWorkspaceExtraAgentDraftAgentId] = useState('')
  const [workspaceExtraAgentTaskDraft, setWorkspaceExtraAgentTaskDraft] = useState('')
  const [workspaceExtraAgentComboboxOpen, setWorkspaceExtraAgentComboboxOpen] = useState(false)
  /** 等待/延迟节点抽屉：各节点已保存的配置 */
  const [workspaceDelayDrawerTimeTypeByNode, setWorkspaceDelayDrawerTimeTypeByNode] = useState<
    Record<string, string>
  >({})
  const [workspaceDelayDrawerTimeTypeDraft, setWorkspaceDelayDrawerTimeTypeDraft] = useState(
    DELAY_DRAWER_DEFAULT_TIME_TYPE,
  )
  const [workspaceDelayTimeTypeComboboxOpen, setWorkspaceDelayTimeTypeComboboxOpen] = useState(false)
  const workspaceDelayTimeTypeComboboxWrapRef = useRef<HTMLDivElement | null>(null)
  /** 旧版「动作事件」配置，仅用于读取历史数据 */
  const [workspaceDelayDrawerModeByNode] = useState<Record<string, string>>({})
  const [workspaceDelayDrawerDurationByNode, setWorkspaceDelayDrawerDurationByNode] = useState<
    Record<string, string>
  >({})
  const [workspaceDelayDrawerUnitByNode, setWorkspaceDelayDrawerUnitByNode] = useState<Record<string, string>>({})
  const [workspaceDelayDrawerDurationDraft, setWorkspaceDelayDrawerDurationDraft] = useState('')
  const [workspaceDelayDrawerUnitDraft, setWorkspaceDelayDrawerUnitDraft] = useState('')
  const [workspaceDelayUnitComboboxOpen, setWorkspaceDelayUnitComboboxOpen] = useState(false)
  const workspaceDelayUnitComboboxWrapRef = useRef<HTMLDivElement | null>(null)
  const [workspaceDelayDrawerReferenceDateByNode, setWorkspaceDelayDrawerReferenceDateByNode] = useState<
    Record<string, string>
  >({})
  const [workspaceDelayDrawerReferenceDateDraft, setWorkspaceDelayDrawerReferenceDateDraft] = useState('')
  const [workspaceDelayReferenceDateComboboxOpen, setWorkspaceDelayReferenceDateComboboxOpen] = useState(false)
  const workspaceDelayReferenceDateComboboxWrapRef = useRef<HTMLDivElement | null>(null)
  const [workspaceDelayDrawerReferenceEventPhaseByNode, setWorkspaceDelayDrawerReferenceEventPhaseByNode] =
    useState<Record<string, string>>({})
  const [workspaceDelayDrawerReferenceEventPhaseDraft, setWorkspaceDelayDrawerReferenceEventPhaseDraft] =
    useState('')
  const [workspaceDelayReferenceEventPhaseComboboxOpen, setWorkspaceDelayReferenceEventPhaseComboboxOpen] =
    useState(false)
  const workspaceDelayReferenceEventPhaseComboboxWrapRef = useRef<HTMLDivElement | null>(null)
  const [workspaceDelayDrawerReferenceTriggerByNode, setWorkspaceDelayDrawerReferenceTriggerByNode] = useState<
    Record<string, string>
  >({})
  const [workspaceDelayDrawerReferenceTriggerDraft, setWorkspaceDelayDrawerReferenceTriggerDraft] = useState('')
  const [workspaceDelayReferenceTriggerComboboxOpen, setWorkspaceDelayReferenceTriggerComboboxOpen] =
    useState(false)
  const workspaceDelayReferenceTriggerComboboxWrapRef = useRef<HTMLDivElement | null>(null)
  const [workspaceDelayDrawerUntilDateByNode, setWorkspaceDelayDrawerUntilDateByNode] = useState<
    Record<string, string>
  >({})
  const [workspaceDelayDrawerUntilTimeByNode, setWorkspaceDelayDrawerUntilTimeByNode] = useState<
    Record<string, string>
  >({})
  const [workspaceDelayDrawerUntilDateDraft, setWorkspaceDelayDrawerUntilDateDraft] = useState('')
  const [workspaceDelayDrawerUntilTimeDraft, setWorkspaceDelayDrawerUntilTimeDraft] = useState('')
  const [workspaceAgentCollectTaskModalOpen, setWorkspaceAgentCollectTaskModalOpen] = useState(false)
  const [workspaceAgentCollectModalDraft, setWorkspaceAgentCollectModalDraft] = useState('')
  const workspaceExtraAgentDrawerIdRef = useRef<string | null>(null)
  const workspaceAgentApplyOptimizeToWorkspaceRef = useRef(false)
  const workspaceAgentComboboxWrapRef = useRef<HTMLDivElement | null>(null)
  const workspaceAgentTaskDrawerTextareaRef = useRef<HTMLTextAreaElement | null>(null)
  const workspaceAgentTaskDrawerHighlightRef = useRef<HTMLDivElement | null>(null)
  const workspaceAgentTaskFileInputRef = useRef<HTMLInputElement | null>(null)
  const workspaceAgentTaskModalTextareaRef = useRef<HTMLTextAreaElement | null>(null)
  const workspaceAgentTaskModalHighlightRef = useRef<HTMLDivElement | null>(null)
  const workspaceAgentTaskSelRef = useRef({ start: 0, end: 0 })
  const workspaceAgentTaskSelTouchedRef = useRef(false)
  const workspaceAgentCollectTaskModalOpenRef = useRef(false)
  /** 当前打开的 Agent 配置抽屉（与画布五类可配置节点一一对应） */
  const [onboardingAgentDrawerKey, setOnboardingAgentDrawerKey] = useState<OnboardingAgentDrawerKey | null>(
    null,
  )
  const [onboardingCollectTaskModalOpen, setOnboardingCollectTaskModalOpen] = useState(false)
  const [collectTaskModalDraft, setCollectTaskModalDraft] = useState('')
  const [onboardingCollectOptimizeModalOpen, setOnboardingCollectOptimizeModalOpen] = useState(false)
  const [collectOptimizePhase, setCollectOptimizePhase] = useState<'thinking' | 'streaming' | 'done'>(
    'thinking',
  )
  const [collectOptimizeStreamText, setCollectOptimizeStreamText] = useState('')
  const [collectOptimizeFooterInput, setCollectOptimizeFooterInput] = useState('')
  const [collectOptimizeStreamRunId, setCollectOptimizeStreamRunId] = useState(0)
  const collectOptimizeActiveLinesRef = useRef<string[]>([...ONBOARDING_OPTIMIZE_LINES])
  const optimizeStreamTextareaRef = useRef<HTMLTextAreaElement | null>(null)
  const collectOptimizeTimersRef = useRef<{ t?: number; i?: number }>({})
  const [taskTextByNode, setTaskTextByNode] = useState(createInitialTaskTexts)
  /** 抽屉内当前编辑的代理人选项（随打开抽屉从 saved 同步） */
  const [agentDrawerDraftId, setAgentDrawerDraftId] = useState('collect')
  /** 各节点上次「保存」的代理人 id，驱动画布标题 */
  const [savedAgentIdByNode, setSavedAgentIdByNode] = useState(createInitialSavedAgentIds)
  const collectTaskModalOpenSnapshotRef = useRef<string>(ONBOARDING_COLLECT_DRAWER_TASK_MARKDOWN)
  const collectTaskModalIsOpenRef = useRef(false)
  const onboardingAgentDrawerKeyRef = useRef<OnboardingAgentDrawerKey | null>(null)
  const savedAgentIdByNodeRef = useRef(savedAgentIdByNode)
  const renameWorkspaceExtraNodeTitle = useCallback((nodeId: string, title: string) => {
    setWorkspaceExtraNodes((prev) => {
      const next = prev.map((node) => (node.id === nodeId ? { ...node, title } : node))
      workspaceExtraNodesRef.current = next
      return next
    })
  }, [])
  const renameCanvasBranchPathTitle = useCallback((pathId: string, nextTitle: string) => {
    const updateTitle = (path: BranchPathDraft) => (path.id === pathId ? { ...path, pathTitle: nextTitle } : path)
    const prevTitle = canvasBranchPathsRef.current.find((path) => path.id === pathId)?.pathTitle?.trim() ?? ''
    setCanvasBranchPaths((prev) => {
      const next = prev.map(updateTitle)
      canvasBranchPathsRef.current = next
      return next
    })
    setBranchPaths((prev) => {
      const next = prev.map(updateTitle)
      branchPathsRef.current = next
      return next
    })
    if (prevTitle && prevTitle !== nextTitle) {
      setBranchShowcaseSavedByTitle((prev) => {
        if (!(prevTitle in prev) || nextTitle in prev) return prev
        const next = { ...prev, [nextTitle]: prev[prevTitle] }
        delete next[prevTitle]
        return next
      })
      setBranchShowcaseActiveTitle((cur) => (cur === prevTitle ? nextTitle : cur))
    }
  }, [])
  const agentComboboxWrapRef = useRef<HTMLDivElement | null>(null)
  const collectTaskFileInputRef = useRef<HTMLInputElement | null>(null)
  const branchLogicFileInputRef = useRef<HTMLInputElement | null>(null)
  const collectTaskDrawerTextareaRef = useRef<HTMLTextAreaElement | null>(null)
  const collectTaskDrawerHighlightRef = useRef<HTMLDivElement | null>(null)
  const collectTaskModalTextareaRef = useRef<HTMLTextAreaElement | null>(null)
  const collectTaskModalHighlightRef = useRef<HTMLDivElement | null>(null)
  const collectTaskSelRef = useRef({ start: 0, end: 0 })
  const collectTaskSelTouchedRef = useRef(false)
  const [agentComboboxOpen, setAgentComboboxOpen] = useState(false)
  /** 从代理人「共同版块」进入的空白详情页（全屏覆盖） */
  const [agentDetailBlankPageOpen, setAgentDetailBlankPageOpen] = useState(false)
  /** Publish：启动代理为应用 — 确认弹窗与成功提示（演示） */
  const [publishAgentAppModalOpen, setPublishAgentAppModalOpen] = useState(false)
  const [publishVersionHistoryOpen, setPublishVersionHistoryOpen] = useState(false)
  const [publishVersionsByScenario, setPublishVersionsByScenario] = useState<
    Record<string, ScenarioPublishVersion[]>
  >({})
  const [pendingScenarioPublish, setPendingScenarioPublish] = useState<{
    sourceName: string
    targetId: string
  } | null>(null)
  const [sectionVersionModalOpen, setSectionVersionModalOpen] = useState(false)
  const [createScenarioModalOpen, setCreateScenarioModalOpen] = useState(false)
  const [createScenarioSuccessToastOpen, setCreateScenarioSuccessToastOpen] = useState(false)
  const createScenarioSuccessToastTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const workflowRunBootTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  const closeScenarioPublishModal = useCallback(() => {
    setPublishAgentAppModalOpen(false)
    setCardPublishScenarioTarget(null)
  }, [])

  const confirmPublishAgentApp = useCallback(
    (targetId: string) => {
      const publishSourceName = cardPublishScenarioTarget?.sourceName ?? selectedScenarioName
      if (publishSourceName == null) return
      const spaceId = resolvePublishSpaceIdFromTargetId(targetId)
      if (!spaceId) return
      setPendingScenarioPublish({ sourceName: publishSourceName, targetId })
      closeScenarioPublishModal()
      setSectionVersionModalOpen(true)
      return false
    },
    [cardPublishScenarioTarget, closeScenarioPublishModal, selectedScenarioName],
  )

  const completeScenarioPublishWithVersion = useCallback(
    (payload: SectionIterationPublishPayload) => {
      if (!pendingScenarioPublish) return
      const { sourceName, targetId } = pendingScenarioPublish
      const spaceId = resolvePublishSpaceIdFromTargetId(targetId)
      if (!spaceId) return

      const displayName = getScenarioDisplayName(sourceName, locale)
      const { publishVersions } = publishWorkflowSectionIteration(
        sourceName,
        {
          sectionType: 'workflow',
          sectionId: sourceName,
          sectionNameZh: displayName,
          sectionNameEn: getScenarioDisplayName(sourceName, 'en'),
          ...payload,
        },
        publishVersionsByScenario,
        locale,
      )

      setPublishVersionsByScenario(publishVersions)
      setPublishedScenarioSourceNames((prev) => new Set([...prev, sourceName]))
      markContentPublished(sourceName, spaceId)
      const scenarioRecord = agents.find((agent) => agent.name === sourceName)
      publishContentToSpace(spaceId, {
        id: sourceName,
        kind: 'workflow',
        sourceModule: 'scenario-config',
        desc: scenarioRecord?.desc,
        meta: scenarioRecord?.meta ?? 'just now',
      })
      addUserContentPublishedTarget(sourceName, {
        spaceId,
        publishedAt: new Date().toISOString(),
        publisherMemberId: resolveCurrentMemberId(),
      })
      setSectionVersionModalOpen(false)
      setPendingScenarioPublish(null)
    },
    [agents, locale, pendingScenarioPublish, publishVersionsByScenario],
  )

  const showCreateScenarioSuccessToast = useCallback(() => {
    setCreateScenarioSuccessToastOpen(true)
    if (createScenarioSuccessToastTimerRef.current) window.clearTimeout(createScenarioSuccessToastTimerRef.current)
    createScenarioSuccessToastTimerRef.current = window.setTimeout(() => {
      createScenarioSuccessToastTimerRef.current = undefined
      setCreateScenarioSuccessToastOpen(false)
    }, 3200)
  }, [])

  const handleCreateScenarioSubmit = useCallback(
    (payload: { description: string; templateTitle: string | null }) => {
      setCreateScenarioModalOpen(false)
      showCreateScenarioSuccessToast()
      setAgents((prev) => {
        const used = new Set(prev.map((x) => x.name))
        const fromTemplate = payload.templateTitle?.trim()
        const newScenarioLabel = scenarioT(locale, 'newScenario')
        let base =
          fromTemplate ||
          payload.description
            .replace(/\s+/g, ' ')
            .trim()
            .slice(0, 48) ||
          newScenarioLabel
        base =
          base
            .replace(/^使用模板：「?[^」]+」?\s*/u, '')
            .replace(/^Using template:\s*"[^"]+"\s*/u, '')
            .trim() || base
        if (!base) base = newScenarioLabel
        let candidate = base
        let n = 0
        while (used.has(candidate)) {
          n += 1
          candidate = `${base} (${n})`
        }
        return [
          {
            name: candidate,
            desc: payload.description,
            meta: 'just now',
            ...(fromTemplate
              ? appMarketTemplateAttribution()
              : manualAgentAttribution(currentCreatorName)),
          },
          ...prev,
        ]
      })
    },
    [locale, showCreateScenarioSuccessToast, currentCreatorName],
  )

  const handleScenarioRenameSave = useCallback(
    (sourceName: string, title: string) => {
      const trimmed = title.trim()
      if (!trimmed) return
      setAgents((prev) =>
        prev.map((a) => (a.name === sourceName ? { ...a, label: trimmed } : a)),
      )
      setRenameScenarioSourceName(null)
    },
    [setAgents],
  )

