  const duplicateScenarioBySourceName = useCallback(
    (sourceName: string, desc: string) => {
      setAgents((prev) => {
        const used = new Set(prev.map((x) => x.name))
        const duplicateName = makeScenarioDuplicateName(sourceName, used)
        const idx = prev.findIndex((x) => x.name === sourceName)
        const original = prev.find((x) => x.name === sourceName)
        const copy: Agent = {
          name: duplicateName,
          desc: original?.desc ?? desc,
          meta: 'just now',
          createdBy: original?.provenance === 'app-market-template' ? undefined : currentCreatorName,
          provenance: original?.provenance === 'app-market-template' ? 'app-market-template' : 'manual',
        }
        return idx === -1 ? [copy, ...prev] : [...prev.slice(0, idx + 1), copy, ...prev.slice(idx + 1)]
      })
      setCardEditScenarioSourceName(null)
    },
    [setAgents, currentCreatorName],
  )

  const scenarioCardActionHandledTokenRef = useRef<number | null>(null)

  useEffect(() => {
    if (!scenarioCardAction?.token) return
    if (scenarioCardActionHandledTokenRef.current === scenarioCardAction.token) return
    const sourceName = scenarioCardAction.sourceName.trim()
    const agent = agents.find((item) => item.name === sourceName)
    if (!agent) {
      scenarioCardActionHandledTokenRef.current = scenarioCardAction.token
      onScenarioCardActionConsumed?.()
      return
    }
    if (scenarioCardAction.action === 'edit') {
      if (canEditScenario && !frozenScenarioSourceNames.has(sourceName)) {
        setCardEditScenarioSourceName(null)
        setScenarioWorkspaceMode('editor')
        setWorkspaceEditorTab('build')
        setSelectedScenarioName(sourceName)
      }
    } else if (canEditScenario) {
      duplicateScenarioBySourceName(sourceName, agent.desc)
    }
    scenarioCardActionHandledTokenRef.current = scenarioCardAction.token
    queueMicrotask(() => onScenarioCardActionConsumed?.())
  }, [
    agents,
    canEditScenario,
    duplicateScenarioBySourceName,
    frozenScenarioSourceNames,
    onScenarioCardActionConsumed,
    scenarioCardAction,
  ])

