  const handleBranchShowcaseTaskFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const { files } = e.target
    if (!files?.length) return
    const names = Array.from(files)
      .map((f) => f.name)
      .join('、')
    const line = `\n\n[附件：${names}]`
    setBranchShowcaseInfoAgentTaskDraft((prev) => `${prev}${line}`)
    e.target.value = ''
  }, [])

  const insertBranchShowcaseTaskReference = useCallback((label: string) => {
    const mentionBody = label.trim()
    if (!mentionBody) return
    const token = `@${mentionBody} `
    setBranchShowcaseInfoAgentTaskDraft((cur) => {
      let start = branchShowcaseTaskSelRef.current.start
      let end = branchShowcaseTaskSelRef.current.end
      if (!branchShowcaseTaskSelTouchedRef.current) {
        start = end = cur.length
      } else {
        start = Math.min(Math.max(0, start), cur.length)
        end = Math.min(Math.max(0, end), cur.length)
        if (start > end) {
          const t = start
          start = end
          end = t
        }
      }
      const before = cur.slice(0, start)
      const after = cur.slice(end)
      const needPad = before.length > 0 && !/\s$/.test(before)
      const insert = (needPad ? ' ' : '') + token
      const next = before + insert + after
      const caret = (before + insert).length
      branchShowcaseTaskSelTouchedRef.current = true
      const useModal = branchShowcaseTaskModalOpen
      queueMicrotask(() => {
        const ta = useModal
          ? branchShowcaseTaskModalTextareaRef.current
          : branchShowcaseTaskDrawerTextareaRef.current
        if (ta) {
          ta.focus()
          ta.setSelectionRange(caret, caret)
        }
        branchShowcaseTaskSelRef.current = { start: caret, end: caret }
      })
      return next
    })
    setBranchShowcaseMentionOpen(false)
  }, [branchShowcaseTaskModalOpen])

  const handleBranchShowcaseTaskTextChange = useCallback((e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const v = e.target.value
    const pos = e.target.selectionStart ?? v.length
    setBranchShowcaseInfoAgentTaskDraft(v)
    if (pos > 0 && v[pos - 1] === '@') {
      if (pos >= 2 && v[pos - 2] === '@') return
      const prev = pos >= 2 ? v[pos - 2] : ' '
      if (pos === 1 || /\s/.test(prev)) {
        setBranchShowcaseMentionOpen(true)
      }
    }
  }, [])

