    const left = Math.max(pad, Math.min(r.left, window.innerWidth - width - pad))
    const preferredTop = r.bottom + 6
    const preferredHeight = 300
    const maxHeightBelow = Math.max(160, window.innerHeight - pad - preferredTop)
    const maxHeightAbove = Math.max(160, r.top - pad - 6)
    const fitsBelow = preferredTop + preferredHeight <= window.innerHeight - pad
    const top = fitsBelow
      ? preferredTop
      : Math.max(pad, r.top - 6 - Math.min(preferredHeight, maxHeightAbove))
    const maxHeight = Math.min(520, fitsBelow ? maxHeightBelow : maxHeightAbove)
    setBranchPathRulesDatePickLayout({ left, top, width, maxHeight })
