  const handleBranchDrawerSave = useCallback(() => {
    if (branchDrawerExtraId) {
      const targets = workspaceBranchDirectOutgoingTargets(
        branchDrawerExtraId,
        workspaceExtraEdges,
        disconnectedWorkspaceEdgeIds,
        removedOnboardingKeys,
        workspaceExtraNodes,
        workspaceAgentDrawerSavedAgentByNode,
      )
      const toSave = branchPathDrawerSavePaths(branchPaths, targets)
      setWorkspaceExtraNodes((nodes) =>
        nodes.map((node) =>
          node.id === branchDrawerExtraId
            ? {
                ...node,
                kind: 'branch-agent',
                branchLogicText: branchLogicText,
                branchPaths: toSave,
              }
            : node,
        ),
      )
      setBranchPaths(toSave)
      branchFormSnapshotRef.current = {
        logic: branchLogicText,
        paths: toSave.map((p) => ({ ...p })),
      }
    } else {
      const normalizedAll = branchPaths.map((p) => {
        const targets = builtinBranchPathDrawerSelectTargets(
          p,
          workspaceExtraEdges,
          disconnectedWorkspaceEdgeIds,
          removedOnboardingKeys,
          workspaceExtraNodes,
          workspaceAgentDrawerSavedAgentByNode,
        )
        const nn = (p.nextNode ?? '').trim()
        return {
          ...p,
          nextNode: targets.some((t) => t.endpointId === nn) ? nn : '',
        }
      })
      const pathsForCanvas = filterBranchPathsForCanvas(
        normalizeBranchPathsForCanvas(normalizedAll),
      )
      setCanvasBranchLogicText(branchLogicText)
      setCanvasBranchPaths(pathsForCanvas)
      setBranchPaths(normalizedAll)
      branchFormSnapshotRef.current = {
        logic: branchLogicText,
        paths: normalizedAll.map((p) => ({ ...p })),
      }
    }
    setBranchMentionOpen(false)
    setBranchLogicModalOpen(false)
    branchPathDescModalPathIdRef.current = null
    setBranchPathDescModalPathId(null)
    setBranchDrawerExtraId(null)
    setBranchDrawerOpen(false)
  }, [
    branchDrawerExtraId,
    branchLogicText,
    branchPaths,
    canvasBranchPaths,
    workspaceExtraEdges,
    disconnectedWorkspaceEdgeIds,
    disconnectedOnboardingBranchForkIds,
    workspaceExtraNodes,
    removedOnboardingKeys,
    workspaceAgentDrawerSavedAgentByNode,
  ])

  /** 画布与抽屉共用：新增一条子路径（独立分支，不自动连下游） */
  const appendCanvasBranchPath = useCallback((partial?: Partial<BranchPathDraft>) => {
    const newPath: BranchPathDraft = {
      ...createNewCanvasBranchPathDraft(branchPathIdSeqRef),
      ...partial,
    }
    if (!branchPathIsConfiguredForCanvas(newPath)) return
    const appendPaths = (paths: BranchPathDraft[]) => filterBranchPathsForCanvas([...paths, newPath])
    setCanvasBranchPaths(appendPaths)
    setBranchPaths((paths) => {
      if (branchDrawerExtraIdRef.current !== null) return paths
      return normalizeBranchPathsForCanvas([...paths, newPath])
    })
  }, [])

  /** 主轴画布「添加路径」：同步写入子路径卡，保证与连线端点 id 一致 */
  const appendBuiltinBranchDrawerPathRow = useCallback(
    (partial?: Partial<BranchPathDraft>): BranchPathDraft => {
      const pathIndex = Math.max(branchPaths.length, canvasBranchPaths.length)
      const pathLabel = String.fromCharCode(65 + pathIndex)
      const newPath: BranchPathDraft = {
        ...createNewCanvasBranchPathDraft(branchPathIdSeqRef),
        nextNode: '',
        description: '',
        pathTitle: `路径 ${pathLabel}`,
        ...partial,
      }
      const nextCanvas = [...canvasBranchPathsRef.current, newPath]
      const nextBranch = [...branchPathsRef.current, newPath]
      canvasBranchPathsRef.current = nextCanvas
      branchPathsRef.current = nextBranch
      setCanvasBranchPaths(nextCanvas)
      setBranchPaths(nextBranch)
      return newPath
    },
    [branchPaths.length, canvasBranchPaths.length],
  )

  /** 条件分支抽屉「增加路径」：主轴同步画布子路径卡；工作区节点仅追加抽屉行 */
  const handleAddBranchPathFromDrawer = useCallback(() => {
    if (branchDrawerExtraIdRef.current) {
      const newPath = createNewCanvasBranchPathDraft(branchPathIdSeqRef)
      setBranchPaths((paths) => [...paths, newPath])
      return
    }
    appendBuiltinBranchDrawerPathRow({})
  }, [appendBuiltinBranchDrawerPathRow])

  const branchCanvasAddPathAnchor = useMemo(() => {
    if (!hasScenarioWorkflowWorkspace(selectedScenarioName, agents)) return null
    if (removedOnboardingKeys.includes('branch')) return null
    return branchCanvasAddPathStemLayout(onboardingNodePos)
  }, [selectedScenarioName, removedOnboardingKeys, onboardingNodePos])

  const workspaceBranchDirectTargets = useMemo(() => {
    if (!branchDrawerExtraId) return []
    return workspaceBranchDirectOutgoingTargets(
      branchDrawerExtraId,
      workspaceExtraEdges,
      disconnectedWorkspaceEdgeIds,
      removedOnboardingKeys,
      workspaceExtraNodes,
      workspaceAgentDrawerSavedAgentByNode,
    )
  }, [
    branchDrawerExtraId,
    workspaceExtraEdges,
    disconnectedWorkspaceEdgeIds,
    removedOnboardingKeys,
    workspaceExtraNodes,
    workspaceAgentDrawerSavedAgentByNode,
  ])

  const deriveBranchDrawerPathsFromCanvas = useCallback(
    (existingPaths: readonly BranchPathDraft[]): BranchPathDraft[] => {
      if (branchDrawerExtraId) {
        return deriveWorkspaceBranchDrawerPaths(
          branchDrawerExtraId,
          existingPaths,
          workspaceExtraEdges,
          disconnectedWorkspaceEdgeIds,
          removedOnboardingKeys,
          workspaceExtraNodes,
          workspaceAgentDrawerSavedAgentByNode,
          () => `branch-path-${branchPathIdSeqRef.current++}`,
        )
      }
      return deriveBuiltinBranchDrawerPaths(
        canvasBranchPaths,
        existingPaths,
        workspaceExtraEdges,
        disconnectedWorkspaceEdgeIds,
        removedOnboardingKeys,
        workspaceExtraNodes,
        workspaceAgentDrawerSavedAgentByNode,
      )
    },
    [
      branchDrawerExtraId,
      canvasBranchPaths,
      workspaceExtraEdges,
      disconnectedWorkspaceEdgeIds,
      removedOnboardingKeys,
      workspaceExtraNodes,
      workspaceAgentDrawerSavedAgentByNode,
    ],
  )

  /** 条件代理抽屉：路径行随画布子路径卡 / 直连 ws 自动同步；抽屉内「增加路径」可追加未连线草稿 */
  useEffect(() => {
    if (!branchDrawerOpen) return
    setBranchPaths((prev) => {
      const next = deriveBranchDrawerPathsFromCanvas(prev)
      return workspaceBranchPathsEqual(prev, next) ? prev : next
    })
  }, [
    branchDrawerOpen,
    branchDrawerExtraId,
    canvasBranchPaths,
    workspaceExtraEdges,
    disconnectedWorkspaceEdgeIds,
    removedOnboardingKeys,
    workspaceExtraNodes,
    workspaceAgentDrawerSavedAgentByNode,
    deriveBranchDrawerPathsFromCanvas,
  ])

  useEffect(() => {
    if (!workspaceNewNodeMenuOpen) return
    const onDoc = (ev: MouseEvent) => {
      const w = workspaceNewNodeWrapRef.current
      if (w && !w.contains(ev.target as Node)) setWorkspaceNewNodeMenuOpen(false)
    }
    const onKey = (ev: KeyboardEvent) => {
      if (ev.key === 'Escape') setWorkspaceNewNodeMenuOpen(false)
    }
    document.addEventListener('mousedown', onDoc)
    window.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('mousedown', onDoc)
      window.removeEventListener('keydown', onKey)
    }
  }, [workspaceNewNodeMenuOpen])

  useEffect(() => {
    if (!asyncProcessingModalOpen) return
    const onKey = (ev: KeyboardEvent) => {
      if (ev.key === 'Escape') {
        setAsyncProcessingModalOpen(false)
        setAsyncProcessingModalTargetNodeId(null)
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [asyncProcessingModalOpen])

  const closeAsyncProcessingModal = useCallback(() => {
    setAsyncProcessingModalOpen(false)
    setAsyncProcessingModalTargetNodeId(null)
    asyncProcessingPendingAddOptionsRef.current = null
    asyncProcessingPendingAutoLinkRef.current = null
  }, [])

  const openAsyncProcessingModalForNewNode = useCallback(
    (pending?: {
      linkToBoardTail?: boolean
      drawerContext?: 'branch' | 'board-tail' | 'add-path'
    }) => {
      asyncProcessingPendingAddOptionsRef.current = pending ?? null
      if (!pending?.linkToBoardTail) {
        asyncProcessingPendingAutoLinkRef.current = null
      }
      setWorkspaceNewNodeMenuOpen(false)
      setAsyncProcessingModalTargetNodeId(null)
      setAsyncProcessingModalOpen(true)
    },
    [],
  )

  const openAsyncProcessingModalForNodeChange = useCallback((nodeId: string) => {
    setAsyncProcessingModalTargetNodeId(nodeId)
    setAsyncProcessingModalOpen(true)
  }, [])

  const closeAsyncAccountConnectFlow = useCallback(() => {
    if (asyncAccountConnectOpenTimerRef.current) {
      clearTimeout(asyncAccountConnectOpenTimerRef.current)
      asyncAccountConnectOpenTimerRef.current = undefined
    }
    setAsyncAccountConnectLoginBtnLoading(false)
    setAsyncAccountConnectOpen(false)
    setAsyncAccountConnectNodeId(null)
    setAsyncAccountConnectAppId(null)
    setAsyncAccountConnectStep('confirm')
    setAsyncAccountConnectEmail('')
    setAsyncAccountConnectCode('')
    setAsyncAccountConnectLoading(false)
    setAsyncAccountConnectResendSec(0)
  }, [])

  const openAsyncAccountConnectFlow = useCallback(
    (nodeId: string, appId: AsyncProcessingThirdPartyAppId) => {
      setAsyncAccountConnectNodeId(nodeId)
      setAsyncAccountConnectAppId(appId)
      setAsyncAccountConnectStep('confirm')
      setAsyncAccountConnectEmail('')
      setAsyncAccountConnectCode('')
      setAsyncAccountConnectLoading(false)
      setAsyncAccountConnectResendSec(0)
      setAsyncAccountConnectOpen(true)
    },
    [],
  )

  const handleAsyncAccountLoginClick = useCallback(
    (nodeId: string, appId: AsyncProcessingThirdPartyAppId) => {
      if (asyncAccountConnectLoginBtnLoading || asyncAccountConnectOpen) return
      setAsyncAccountConnectLoginBtnLoading(true)
      if (asyncAccountConnectOpenTimerRef.current) {
        clearTimeout(asyncAccountConnectOpenTimerRef.current)
      }
      asyncAccountConnectOpenTimerRef.current = window.setTimeout(() => {
        asyncAccountConnectOpenTimerRef.current = undefined
        openAsyncAccountConnectFlow(nodeId, appId)
        setAsyncAccountConnectLoginBtnLoading(false)
      }, ASYNC_ACCOUNT_CONNECT_OPEN_MS)
    },
    [asyncAccountConnectLoginBtnLoading, asyncAccountConnectOpen, openAsyncAccountConnectFlow],
  )

  const completeAsyncAccountConnectFlow = useCallback(() => {
    const nodeId = asyncAccountConnectNodeId
    const appId = asyncAccountConnectAppId
    if (!nodeId || !appId) {
      closeAsyncAccountConnectFlow()
      return
    }
    const appName = getAsyncProcessingAppById(appId).name
    const connectionKey = asyncAccountConnectionKey(nodeId, appId)
    setWorkspaceAsyncAccountConnectedByNode((prev) => ({ ...prev, [connectionKey]: true }))
    closeAsyncAccountConnectFlow()
    if (asyncAccountConnectSuccessToastTimerRef.current) {
      clearTimeout(asyncAccountConnectSuccessToastTimerRef.current)
    }
    setAsyncAccountConnectSuccessToast(appName)
    asyncAccountConnectSuccessToastTimerRef.current = setTimeout(() => {
      setAsyncAccountConnectSuccessToast(null)
      asyncAccountConnectSuccessToastTimerRef.current = undefined
    }, 4200)
  }, [asyncAccountConnectNodeId, asyncAccountConnectAppId, closeAsyncAccountConnectFlow])

  const handleAsyncAccountConnectEmailContinue = useCallback(() => {
    const email = asyncAccountConnectEmail.trim()
    if (!email || asyncAccountConnectLoading) return
    setAsyncAccountConnectLoading(true)
    window.setTimeout(() => {
      setAsyncAccountConnectLoading(false)
      setAsyncAccountConnectStep('verify')
      setAsyncAccountConnectResendSec(ASYNC_ACCOUNT_CONNECT_RESEND_SEC)
    }, ASYNC_ACCOUNT_CONNECT_LOADING_MS)
  }, [asyncAccountConnectEmail, asyncAccountConnectLoading])

  const handleAsyncAccountConnectCodeContinue = useCallback(() => {
    if (!/^\d{6}$/.test(asyncAccountConnectCode.trim()) || asyncAccountConnectLoading) return
    setAsyncAccountConnectLoading(true)
    window.setTimeout(() => {
      setAsyncAccountConnectLoading(false)
      completeAsyncAccountConnectFlow()
    }, 900)
  }, [asyncAccountConnectCode, asyncAccountConnectLoading, completeAsyncAccountConnectFlow])

  useEffect(() => {
    if (!asyncAccountConnectOpen) return
    const onKey = (ev: KeyboardEvent) => {
      if (ev.key === 'Escape' && !asyncAccountConnectLoading) closeAsyncAccountConnectFlow()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [asyncAccountConnectOpen, asyncAccountConnectLoading, closeAsyncAccountConnectFlow])

  useEffect(() => {
    if (asyncAccountConnectStep !== 'verify' || asyncAccountConnectResendSec <= 0) return
    const timer = window.setInterval(() => {
      setAsyncAccountConnectResendSec((sec) => (sec > 0 ? sec - 1 : 0))
    }, 1000)
    return () => window.clearInterval(timer)
  }, [asyncAccountConnectStep, asyncAccountConnectResendSec])

  useEffect(
    () => () => {
      if (asyncAccountConnectSuccessToastTimerRef.current) {
        clearTimeout(asyncAccountConnectSuccessToastTimerRef.current)
      }
      if (asyncAccountConnectOpenTimerRef.current) {
        clearTimeout(asyncAccountConnectOpenTimerRef.current)
      }
    },
    [],
  )

  const addWorkspaceNodeFromMenu = useCallback(
    (
      kind: WorkspaceNewNodeKind,
      options?: {
        linkToBoardTail?: boolean
        consumeDrawerAutoLink?: boolean
        /** 紧挨主轴内置条件代理主卡下方放置并连线（「添加路径」选条件代理） */
        anchorBelowOnboardingBranch?: boolean
        /** 从指定子路径卡底连线并放置节点（主轴「添加路径」与工作区节点一一对应） */
        linkFromBranchPathId?: string
        /** 工作区节点占据子路径分叉位（不另建子路径卡 + 底连线，避免重复节点） */
        occupyBranchSubPathSlot?: boolean
        insertToEndpointId?: string
        asyncAppId?: AsyncProcessingThirdPartyAppId
      },
    ) => {
      const resolvedKind: WorkspaceNewNodeKind =
        kind === 'branch' || kind === 'branch-agent' ? 'branch-agent' : kind
      const h = WORKSPACE_NEW_NODE_HEIGHT[resolvedKind]
      const vp = workflowViewportRef.current
      const idx = workspaceExtraNodesRef.current.length
      const id = `ws-${workspaceExtraIdSeqRef.current++}`

      let x: number
      let y: number
      let tailFromId: string | null = null
      let insertToEndpointId: string | undefined = options?.insertToEndpointId
      let disconnectInsertedEdge: WorkflowInsertedEdgeDisconnectSpec | undefined = options?.disconnectInsertedEdge
      let useCompactBoard = options?.anchorBelowOnboardingBranch === true
      if (
        options?.linkFromBranchPathId &&
        !removedOnboardingKeys.includes('branch')
      ) {
        const branchPos = onboardingNodePosRef.current.branch
        const pathsNow = canvasBranchPathsRef.current
        const pathIdx = pathsNow.findIndex((p) => p.id === options.linkFromBranchPathId)
        const subPos =
          pathIdx >= 0
            ? onboardingBranchSubPosByIdRef.current[options.linkFromBranchPathId] ??
              defaultBranchSubCardTopleft(branchPos, pathsNow.length, pathIdx)
            : null
        if (subPos) {
          const nodeW = workspaceExtraNodeBoardWidth({ compactBoard: true })
          x = subPos.x + (WORKFLOW_BRANCH_SUB_CARD_W - nodeW) / 2
          if (options?.occupyBranchSubPathSlot) {
            y = subPos.y
            tailFromId = null
          } else {
            y = subPos.y + WORKFLOW_BRANCH_SUB_CARD_H + ONBOARDING_WORKFLOW_LAYER_GAP_Y
            tailFromId = onboardingBranchSubWorkspaceEdgeEndpoint(options.linkFromBranchPathId)
          }
          useCompactBoard = true
        } else {
          const c = boardCoordsForNewWorkspaceNode(
            vp,
            workspaceCanvasZoom,
            workspaceExtraNodeBoardWidth({ compactBoard: true }),
            h,
            idx,
          )
          x = c.x
          y = c.y
        }
      } else if (options?.anchorBelowOnboardingBranch && !removedOnboardingKeys.includes('branch')) {
        const b = onboardingNodePosRef.current.branch
        const branchEp = onboardingWorkspaceEdgeEndpoint('branch')
        const extrasNow = workspaceExtraNodesRef.current
        const edgesNow = workspaceExtraEdgesRef.current
        const chainTail = resolveAnchorBelowOnboardingBranchTailFromId(
          branchEp,
          edgesNow,
          disconnectedWorkspaceEdgeIds,
          extrasNow,
        )
        const tailNode = extrasNow.find((n) => n.id === chainTail)
        if (tailNode) {
          x = tailNode.x
          y =
            tailNode.y +
            WORKSPACE_NEW_NODE_HEIGHT[tailNode.kind] +
            ONBOARDING_WORKFLOW_LAYER_GAP_Y
          tailFromId = chainTail
        } else {
          x = b.x + (WORKFLOW_NODE_WIDTH - workspaceExtraNodeBoardWidth()) / 2
          y = b.y + WORKFLOW_BRANCH_MAIN_CARD_H + ONBOARDING_WORKFLOW_LAYER_GAP_Y
          tailFromId = branchEp
        }
      } else if (options?.linkToBoardTail) {
        let spec: {
          fromEndpointId: string
          top: number
          centerX: number
          toEndpointId?: string
          disconnectSpec?: WorkflowInsertedEdgeDisconnectSpec
        } | null = null
        if (options.consumeDrawerAutoLink !== false) {
          spec = addStepDrawerAutoLinkFromRef.current
          addStepDrawerAutoLinkFromRef.current = null
        }
        const extrasNow = workspaceExtraNodesRef.current
        let linkTop: number | null = null
        let linkCenterX: number | null = null
        let linkFromId: string | null = null
        if (spec) {
          linkTop = spec.top
          linkCenterX = spec.centerX
          linkFromId = spec.fromEndpointId
          insertToEndpointId = spec.toEndpointId
          disconnectInsertedEdge = spec.disconnectSpec
        } else {
          const anchor = workflowBoardBottomAddLinkAnchor(
            onboardingNodePos,
            removedOnboardingKeys,
            extrasNow,
          )
          if (anchor) {
            linkTop = anchor.top
            linkCenterX = anchor.centerX
            linkFromId = anchor.fromEndpointId
          }
        }
        if (
          !useCompactBoard &&
          linkFromId &&
          workspaceEndpointIsBranchAgentOutlet(linkFromId, extrasNow, removedOnboardingKeys)
        ) {
          useCompactBoard = true
        }
        const nodeW = workspaceExtraNodeBoardWidth({ compactBoard: useCompactBoard })
        if (linkTop != null && linkCenterX != null && linkFromId) {
          x = linkCenterX - nodeW / 2
          y = linkTop + ONBOARDING_WORKFLOW_LAYER_GAP_Y
          tailFromId = linkFromId
        } else {
          const c = boardCoordsForNewWorkspaceNode(vp, workspaceCanvasZoom, nodeW, h, idx)
          x = c.x
          y = c.y
        }
      } else {
        const nodeW = workspaceExtraNodeBoardWidth(resolvedKind)
        const c = boardCoordsForNewWorkspaceNode(vp, workspaceCanvasZoom, nodeW, h, idx)
        x = c.x
        y = c.y
      }

      if (
        !useCompactBoard &&
        tailFromId &&
        workspaceEndpointIsBranchAgentOutlet(
          tailFromId,
          workspaceExtraNodesRef.current,
          removedOnboardingKeys,
        )
      ) {
        useCompactBoard = true
      }

      const compactBoard = useCompactBoard
      const asyncAppMeta = options?.asyncAppId ? getAsyncProcessingAppById(options.asyncAppId) : null
      const asyncNodeExtras = asyncAppMeta
        ? { asyncAppId: asyncAppMeta.id, title: asyncAppMeta.name }
        : {}
      const nextNodes =
        resolvedKind === 'branch-agent'
          ? [
              ...workspaceExtraNodesRef.current,
              {
                id,
                kind: 'branch-agent' as const,
                x,
                y,
                branchLogicText: '',
                branchPaths: [],
                ...(compactBoard ? { compactBoard: true } : {}),
              },
            ]
          : [
              ...workspaceExtraNodesRef.current,
              { id, kind: resolvedKind, x, y, ...(compactBoard ? { compactBoard: true } : {}), ...asyncNodeExtras },
            ]
      workspaceExtraNodesRef.current = nextNodes
      setWorkspaceExtraNodes(nextNodes)
      if (resolvedKind === 'schedule') {
        setWorkspaceScheduleConfigByNode((prev) => ({
          ...prev,
          [id]: cloneScheduleNodeConfig(DEFAULT_SCHEDULE_NODE_CONFIG),
        }))
      }
      if (tailFromId || insertToEndpointId) {
        const appendedEdges: WorkspaceExtraEdge[] = []
        if (tailFromId) {
          appendedEdges.push({
            id: `wse-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
            from: tailFromId,
            to: id,
          })
        }
        if (insertToEndpointId) {
          appendedEdges.push({
            id: `wse-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`,
            from: resolvedKind === 'manual' ? workspaceManualBranchEndpoint(id, 'agree') : id,
            to: insertToEndpointId,
          })
        }
        const nextEdges = [...workspaceExtraEdgesRef.current, ...appendedEdges]
        setWorkspaceExtraEdgesSynced(nextEdges)
      }
      if (disconnectInsertedEdge?.kind === 'spine') {
        setDisconnectedOnboardingSpineEdgeKeys((prev) =>
          prev.includes(disconnectInsertedEdge.edgeKey) ? prev : [...prev, disconnectInsertedEdge.edgeKey],
        )
      } else if (disconnectInsertedEdge?.kind === 'branch-fork') {
        setDisconnectedOnboardingBranchForkIds((prev) =>
          prev.includes(disconnectInsertedEdge.edgeKey) ? prev : [...prev, disconnectInsertedEdge.edgeKey],
        )
      } else if (disconnectInsertedEdge?.kind === 'workspace') {
        setDisconnectedWorkspaceEdgeIdsSynced((prev) =>
          prev.includes(disconnectInsertedEdge.edgeId) ? prev : [...prev, disconnectInsertedEdge.edgeId],
        )
      }
      setWorkspaceNewNodeMenuOpen(false)
      return id
    },
    [workspaceCanvasZoom, onboardingNodePos, removedOnboardingKeys, disconnectedWorkspaceEdgeIds, setDisconnectedWorkspaceEdgeIdsSynced, setWorkspaceExtraEdgesSynced],
  )

  /** 主轴「添加路径」：在画布追加子路径卡并连线 */
  const resolveOrCreateBuiltinBranchPathForMenu = useCallback(
    (partial: Partial<BranchPathDraft>): BranchPathDraft => {
      return appendBuiltinBranchDrawerPathRow(partial)
    },
    [appendBuiltinBranchDrawerPathRow],
  )

  /** 「添加路径」抽屉：创建子路径元数据 + 单个工作区节点（占据分叉位，不重复渲染子路径卡） */
  const addBranchPathFromMenu = useCallback(
    (kind: WorkspaceNewNodeKind) => {
      const bindPathNextNode = (pathId: string, endpointId: string) => {
        const bind = (p: BranchPathDraft) =>
          p.id === pathId ? { ...p, nextNode: endpointId } : p
        const nextCanvas = canvasBranchPathsRef.current.map(bind)
        const nextBranch = branchPathsRef.current.map(bind)
        canvasBranchPathsRef.current = nextCanvas
        branchPathsRef.current = nextBranch
        setCanvasBranchPaths(nextCanvas)
        setBranchPaths(nextBranch)
      }
      const placeOnForkSlot = { occupyBranchSubPathSlot: true as const }
      if (kind === 'agent') {
        const newPath = resolveOrCreateBuiltinBranchPathForMenu({})
        const wsId = addWorkspaceNodeFromMenu('agent', {
          linkFromBranchPathId: newPath.id,
          ...placeOnForkSlot,
        })
        if (wsId) bindPathNextNode(newPath.id, wsId)
        return
      }
      if (kind === 'branch-agent' || kind === 'branch') {
        const newPath = resolveOrCreateBuiltinBranchPathForMenu({})
        const wsId = addWorkspaceNodeFromMenu('branch-agent', {
          linkFromBranchPathId: newPath.id,
          ...placeOnForkSlot,
        })
        if (wsId) bindPathNextNode(newPath.id, wsId)
        return
      }
      if (kind === 'manual') {
        const newPath = resolveOrCreateBuiltinBranchPathForMenu({})
        const wsId = addWorkspaceNodeFromMenu('manual', {
          linkFromBranchPathId: newPath.id,
          ...placeOnForkSlot,
        })
        if (wsId) bindPathNextNode(newPath.id, wsId)
        return
      }
      const opt = BRANCH_ADD_STEP_DRAWER_MENU_OPTIONS.find((o) => o.id === kind)
      resolveOrCreateBuiltinBranchPathForMenu({
        nextNode: '',
        pathTitle: opt?.title ?? '',
        description: opt?.desc ?? '',
      })
    },
    [resolveOrCreateBuiltinBranchPathForMenu, addWorkspaceNodeFromMenu],
  )

  const handleAsyncProcessingAppPick = useCallback(
    (appId: AsyncProcessingThirdPartyAppId) => {
      const appMeta = getAsyncProcessingAppById(appId)
      const targetNodeId = asyncProcessingModalTargetNodeId
      if (targetNodeId) {
        if (
          asyncAccountConnectOpen &&
          asyncAccountConnectNodeId === targetNodeId &&
          asyncAccountConnectAppId !== appId
        ) {
          closeAsyncAccountConnectFlow()
        }
        setWorkspaceExtraNodes((prev) =>
          prev.map((n) =>
            n.id === targetNodeId ? { ...n, asyncAppId: appId, title: appMeta.name } : n,
          ),
        )
        closeAsyncProcessingModal()
        return
      }

      const pending = asyncProcessingPendingAddOptionsRef.current
      asyncProcessingPendingAddOptionsRef.current = null

      if (pending?.linkToBoardTail && asyncProcessingPendingAutoLinkRef.current) {
        addStepDrawerAutoLinkFromRef.current = asyncProcessingPendingAutoLinkRef.current
      }
      asyncProcessingPendingAutoLinkRef.current = null

      let newNodeId: string
      if (pending?.drawerContext === 'add-path') {
        const newPath = resolveOrCreateBuiltinBranchPathForMenu({})
        newNodeId = addWorkspaceNodeFromMenu('async', {
          asyncAppId: appId,
          linkFromBranchPathId: newPath.id,
          occupyBranchSubPathSlot: true,
        })
        const bind = (p: BranchPathDraft) =>
          p.id === newPath.id ? { ...p, nextNode: newNodeId } : p
        const nextCanvas = canvasBranchPathsRef.current.map(bind)
        const nextBranch = branchPathsRef.current.map(bind)
        canvasBranchPathsRef.current = nextCanvas
        branchPathsRef.current = nextBranch
        setCanvasBranchPaths(nextCanvas)
        setBranchPaths(nextBranch)
      } else {
        newNodeId = addWorkspaceNodeFromMenu('async', {
          asyncAppId: appId,
          linkToBoardTail: pending?.linkToBoardTail,
        })
      }

      setWorkspaceManualConfigDrawerId(null)
      setWorkspaceExtraAgentDrawerId(newNodeId)
      closeAsyncProcessingModal()
    },
    [
      asyncProcessingModalTargetNodeId,
      addWorkspaceNodeFromMenu,
      asyncAccountConnectAppId,
      asyncAccountConnectNodeId,
      asyncAccountConnectOpen,
      closeAsyncAccountConnectFlow,
      closeAsyncProcessingModal,
      resolveOrCreateBuiltinBranchPathForMenu,
    ],
  )

  const closeCollectTaskModalSave = useCallback(() => {
    const key = onboardingAgentDrawerKeyRef.current
    if (key) {
      setTaskTextByNode((prev) => ({
        ...prev,
        [key]: collectTaskModalDraft,
      }))
    }
    setOnboardingCollectTaskModalOpen(false)
  }, [collectTaskModalDraft])

  const handleCollectTaskFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const { files } = e.target
    if (!files?.length) return
    const k = onboardingAgentDrawerKeyRef.current
    if (!k) return
    const names = Array.from(files)
      .map((f) => f.name)
      .join('、')
    const line = `\n\n[附件：${names}]`
    if (collectTaskModalIsOpenRef.current) {
      setCollectTaskModalDraft((prev) => `${prev}${line}`)
    } else {
      setTaskTextByNode((prev) => ({
        ...prev,
        [k]: `${taskTextForOnboardingNode(prev, k)}${line}`,
      }))
    }
    e.target.value = ''
  }, [])

  const handleBranchLogicFileChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const { files } = e.target
    if (!files?.length) return
    const names = Array.from(files)
      .map((f) => f.name)
      .join('、')
    const line = `\n\n[附件：${names}]`
    setBranchLogicText((prev) => `${prev}${line}`)
    e.target.value = ''
  }, [])

  const revertAgentSelectionToSnapshot = useCallback(() => {
    const k = onboardingAgentDrawerKeyRef.current
    const snap = savedAgentIdAtDrawerOpenRef.current
    if (!k || snap == null) return
    const restored = clampAgentIdForDrawer(k, snap)
    setSavedAgentIdByNode((p) => ({ ...p, [k]: restored }))
    setAgentDrawerDraftId(restored)
  }, [])

  /** 工作区用户新增 Trigger：打开/关闭与画布内置 Trigger 相同的「更改触发器」抽屉 */
  const handleWorkspaceTriggerActivate = useCallback(
    (nodeId: string) => {
      setBranchDrawerOpen(false)
      setWorkspaceExtraAgentDrawerId(null)
      setWorkspaceManualConfigDrawerId(null)
      setOnboardingAgentDrawerKey((prev) => {
        if (!prev) return null
        if (collectTaskModalIsOpenRef.current) {
          setTaskTextByNode((t) => ({
            ...t,
            [prev]: collectTaskModalOpenSnapshotRef.current,
          }))
        }
        setOnboardingCollectTaskModalOpen(false)
        setOnboardingCollectOptimizeModalOpen(false)
        revertAgentSelectionToSnapshot()
        return null
      })
      if (triggerManualDetailDrawerOpen && workspaceExtraNodeAccentOpenId === nodeId) {
        closeTriggerChangeDrawer()
        return
      }
      if (triggerScheduledDetailDrawerOpen && workspaceExtraNodeAccentOpenId === nodeId) {
        closeTriggerChangeDrawer()
        return
      }
      if (triggerFormDetailDrawerOpen && workspaceExtraNodeAccentOpenId === nodeId) {
        closeTriggerChangeDrawer()
        return
      }
      if (triggerChangeDrawerOpen && workspaceExtraNodeAccentOpenId === nodeId) {
        closeTriggerChangeDrawer()
        return
      }
      setTriggerManualDetailDrawerOpen(false)
      setTriggerScheduledDetailDrawerOpen(false)
      setTriggerFormDetailDrawerOpen(false)
      setTriggerFormInputTypeMenuOpen(false)
      setFormTriggerRunInputRows([])
      setTriggerDrawerSearchQuery('')
      setTriggerChangeDrawerOpen(true)
      setWorkspaceExtraNodeAccentOpenId(nodeId)
      setOnboardingTriggerAccentOpen(false)
    },
    [
      triggerManualDetailDrawerOpen,
      triggerScheduledDetailDrawerOpen,
      triggerFormDetailDrawerOpen,
      triggerChangeDrawerOpen,
      workspaceExtraNodeAccentOpenId,
      closeTriggerChangeDrawer,
      revertAgentSelectionToSnapshot,
    ],
  )

  /** 主轴内置「条件分支」：打开左侧无遮罩配置抽屉，并收起路径规则等子面板以免占位 */
  const openBuiltinBranchConfigDrawer = useCallback(() => {
    if (!OPEN_BRANCH_DRAWER_ON_WORKSPACE_BRANCH_CLICK) return
    closeBranchCanvasPathRules()
    closeBranchCanvasAddStepDrawer()
    setBranchAddStepEmailConfigOpen(false)
    setBranchMentionOpen(false)
    setTriggerChangeDrawerOpen(false)
    setTriggerManualDetailDrawerOpen(false)
    setTriggerScheduledDetailDrawerOpen(false)
    setTriggerFormDetailDrawerOpen(false)
    setTriggerManualInputTypeMenuOpen(false)
    setManualTriggerRunInputRows([])
    setTriggerFormInputTypeMenuOpen(false)
    setFormTriggerRunInputRows([])
    setWorkspaceExtraAgentDrawerId(null)
    setWorkspaceManualConfigDrawerId(null)
    setBranchDrawerOpen((wasOpen) => {
      if (wasOpen && branchDrawerExtraIdRef.current === null) {
        return false
      }
      const logic = canvasBranchLogicTextRef.current
      const mergedRawPaths = mergeBuiltinBranchDrawerPathRows(
        canvasBranchPathsRef.current,
        branchPathsRef.current,
      ).map((p) => ({ ...p }))
      const migrated = migrateLegacyBuiltinCanvasBranchPaths(mergedRawPaths)
      const canvasPaths =
        migrated.length > 0 ? migrated : defaultBranchPathsForCanvas()
      const paths = deriveBuiltinBranchDrawerPaths(
        canvasPaths,
        branchPathsRef.current,
        workspaceExtraEdgesRef.current,
        disconnectedWorkspaceEdgeIds,
        removedOnboardingKeysRef.current,
        workspaceExtraNodesRef.current,
        workspaceAgentDrawerSavedAgentByNode,
      )
      const didMigrateBuiltinBranchNextNodes =
        paths.some((p, i) => p.nextNode !== mergedRawPaths[i]?.nextNode) ||
        paths.some((p, i) => p.nextNode !== migrated[i]?.nextNode) ||
        canvasPaths.length !== canvasBranchPathsRef.current.length ||
        canvasPaths.some((p, i) => canvasBranchPathsRef.current[i]?.id !== p.id)
      flushSync(() => {
        setBranchDrawerExtraId(null)
        setBranchLogicText(logic)
        if (didMigrateBuiltinBranchNextNodes) setCanvasBranchPaths(canvasPaths)
        setBranchPaths(paths)
      })
      branchFormSnapshotRef.current = {
        logic,
        paths: paths.map((p) => ({ ...p })),
      }
      setOnboardingAgentDrawerKey((prev) => {
        if (!prev) return null
        if (collectTaskModalIsOpenRef.current) {
          setTaskTextByNode((t) => ({
            ...t,
            [prev]: collectTaskModalOpenSnapshotRef.current,
          }))
        }
        setOnboardingCollectTaskModalOpen(false)
        setOnboardingCollectOptimizeModalOpen(false)
        revertAgentSelectionToSnapshot()
        return null
      })
      return true
    })
  }, [
    closeBranchCanvasPathRules,
    closeBranchCanvasAddStepDrawer,
    revertAgentSelectionToSnapshot,
    disconnectedWorkspaceEdgeIds,
    disconnectedOnboardingBranchForkIds,
    workspaceAgentDrawerSavedAgentByNode,
  ])

  /** 工作区「条件分支 / 条件代理」节点：打开左侧配置抽屉；条件代理无已存数据时为空白表单 */
  const openWorkspaceExtraBranchDrawerForNode = useCallback((n: WorkspaceExtraNode) => {
    if (!OPEN_BRANCH_DRAWER_ON_WORKSPACE_BRANCH_CLICK) return
    if (n.kind !== 'branch' && n.kind !== 'branch-agent') return
    closeBranchCanvasPathRules()
    closeBranchCanvasAddStepDrawer()
    setBranchAddStepEmailConfigOpen(false)
    setBranchMentionOpen(false)
    setTriggerChangeDrawerOpen(false)
    setTriggerManualDetailDrawerOpen(false)
    setTriggerScheduledDetailDrawerOpen(false)
    setTriggerFormDetailDrawerOpen(false)
    setTriggerManualInputTypeMenuOpen(false)
    setManualTriggerRunInputRows([])
    setTriggerFormInputTypeMenuOpen(false)
    setFormTriggerRunInputRows([])
    setWorkspaceExtraAgentDrawerId(null)
    setWorkspaceManualConfigDrawerId(null)
    setBranchDrawerOpen((wasOpen) => {
      if (wasOpen && branchDrawerExtraIdRef.current === n.id) {
        setBranchDrawerExtraId(null)
        return false
      }
      const logic = n.branchLogicText ?? ''
      const rawPaths =
        n.branchPaths && n.branchPaths.length > 0 ? n.branchPaths.map((p) => ({ ...p })) : []
      const paths = deriveWorkspaceBranchDrawerPaths(
        n.id,
        rawPaths,
        workspaceExtraEdgesRef.current,
        disconnectedWorkspaceEdgeIds,
        removedOnboardingKeysRef.current,
        workspaceExtraNodesRef.current,
        workspaceAgentDrawerSavedAgentByNode,
        () => `branch-path-${branchPathIdSeqRef.current++}`,
      )
      flushSync(() => {
        setBranchDrawerExtraId(n.id)
        setBranchLogicText(logic)
        setBranchPaths(paths)
      })
      branchFormSnapshotRef.current = {
        logic,
        paths: paths.map((p) => ({ ...p })),
      }
      setOnboardingAgentDrawerKey((prev) => {
        if (!prev) return null
        if (collectTaskModalIsOpenRef.current) {
          setTaskTextByNode((t) => ({
            ...t,
            [prev]: collectTaskModalOpenSnapshotRef.current,
          }))
        }
        setOnboardingCollectTaskModalOpen(false)
        setOnboardingCollectOptimizeModalOpen(false)
        revertAgentSelectionToSnapshot()
        return null
      })
      return true
    })
  }, [
    closeBranchCanvasPathRules,
    closeBranchCanvasAddStepDrawer,
    revertAgentSelectionToSnapshot,
    disconnectedWorkspaceEdgeIds,
    workspaceAgentDrawerSavedAgentByNode,
  ])

  /** 工作区条件代理：主轴出口挂载的节点打开主轴抽屉，独立 ws 条件代理打开自身抽屉 */
  const openBranchDrawerForWorkspaceExtraNode = useCallback(
    (n: WorkspaceExtraNode) => {
      if (
        n.kind === 'branch-agent' &&
        workspaceNodeIsAttachedToBuiltinBranchZone(
          n.id,
          workspaceExtraEdgesRef.current,
          disconnectedWorkspaceEdgeIds,
          removedOnboardingKeysRef.current,
        )
      ) {
        openBuiltinBranchConfigDrawer()
        return
      }
      openWorkspaceExtraBranchDrawerForNode(n)
    },
    [
      openBuiltinBranchConfigDrawer,
      openWorkspaceExtraBranchDrawerForNode,
      disconnectedWorkspaceEdgeIds,
    ],
  )

