  /**
   * 自愈：当画布上存在预置的「用户配置」节点，但 training/office/master 仍处于 pre-shift 的默认位置
   * （多见于开发态 HMR 保留旧 state 的情况），自动把它们推到正确 y。运行一次即可。
   */
  const initialLayoutHealedRef = useRef(false)
  useEffect(() => {
    if (initialLayoutHealedRef.current) return
    const hasPresetUserConfig = workspaceExtraNodes.some((n) => n.id === DEFAULT_USER_CONFIG_NODE_ID)
    if (!hasPresetUserConfig) {
      initialLayoutHealedRef.current = true
      return
    }
    const trainingPos = onboardingNodePos.training
    if (!trainingPos) return
    const expectedY =
      DEFAULT_ONBOARDING_NODE_POS.training.y + DEFAULT_USER_CONFIG_TRAINING_OFFSET_Y
    /** 仅当 training 还在 pre-shift 的默认位置时才纠正，避免覆盖用户已经拖动过的位置 */
    if (trainingPos.y === DEFAULT_ONBOARDING_NODE_POS.training.y && trainingPos.y !== expectedY) {
      setOnboardingNodePos((prev) => {
        const next = { ...prev }
        for (const k of ['training', 'office', 'master'] as OnboardingBoardNodeKey[]) {
          if (prev[k] && prev[k].y === DEFAULT_ONBOARDING_NODE_POS[k].y) {
            next[k] = {
              x: prev[k].x,
              y: DEFAULT_ONBOARDING_NODE_POS[k].y + DEFAULT_USER_CONFIG_TRAINING_OFFSET_Y,
            }
          }
        }
        return next
      })
    }
    initialLayoutHealedRef.current = true
  }, [workspaceExtraNodes, onboardingNodePos])

