      setWorkspaceExtraNodes(DEFAULT_WORKSPACE_EXTRA_NODES.map((node) => ({ ...node })))
      setWorkspaceExtraEdgesSynced(DEFAULT_WORKSPACE_EXTRA_EDGES.map((edge) => ({ ...edge })))
      setScenarioWorkspaceMode('editor')
