      setWorkspaceExtraNodes(DEFAULT_WORKSPACE_EXTRA_NODES.map((n) => ({ ...n })))
      setWorkspaceExtraEdgesSynced(DEFAULT_WORKSPACE_EXTRA_EDGES.map((e) => ({ ...e })))
      workspaceEdgeConnectDetachRef.current?.()
